"""Individually revised articles based on the thirty selected user manuscripts."""
ARTICLES=[]
SOURCES={
 'sleep':('CDC 수면 안내','https://www.cdc.gov/sleep/about/'),
 'learning':('미국 교육과학연구소 학습 방법 안내','https://ies.ed.gov/ncee/wwc/PracticeGuide/1'),
 'motivation':('Ryan·Deci의 학습 동기 연구','https://selfdeterminationtheory.org/wp-content/uploads/2020/06/2020_RyanDeci_IntrinsicandExtrinsic.pdf'),
 'fees':('교육부 학원 정보 공개 안내','https://www.moe.go.kr/boardCnts/viewRenew.do?boardID=340&boardSeq=99235&lev=0&m=0302&opType=N&page=46&s=moe'),
 'support':('청소년상담1388','https://www.1388.go.kr/'),
 'wawa':('와와 공식 학습코칭 안내','https://www.wawacenter.com/intro/coachingSystem'),
}
GROUPS=['시험 준비','계획·시간 관리','과목·복습','동기·습관','학원·코칭','생활·학부모']
def add(n,slug,title,desc,group,stages,subjects,lead,sections,task,faq,sources=()):
 ARTICLES.append(dict(sourceIndex=n-1,slug=slug,title=title,description=desc,group=GROUPS[group],stages=list(stages),subjects=subjects.split('·') if subjects else [],lead=lead,sections=sections,task=task,faq=faq,sources=list(sources)))

add(1,'기말고사시간부족','기말고사 시간이 부족할 때 공부 범위를 줄이는 방법',
 '기말고사까지 남은 시간에 맞춰 시험 범위를 나누고, 우선 과제와 재풀이·시험 전 준비를 정리합니다.',0,'중고','',
 '시험이 가까워지면 새 문제집을 끝내려는 마음부터 들 수 있습니다. 먼저 학교에서 안내한 범위와 지금 혼자 할 수 있는 내용을 구분하세요. 남은 시간에 무엇을 확인할지 정하는 것이 이 글의 출발점입니다.',[
 ('남은 날짜보다 실제 사용할 시간을 보기','시험 날짜를 적은 뒤 학교·등원·식사·수면 시간을 제외합니다. 남은 칸에 할 수 있는 과제만 넣어야 합니다. 밤샘을 전제로 세운 계획은 다음 날의 공부까지 흔들 수 있습니다. 하루를 일률적으로 세 시간씩 나누기보다 이미 정해진 생활 일정 사이에 과제를 배치하세요.'),
 ('학교가 안내한 범위를 한곳에 모으기','교과서 쪽수, 수업 자료, 수행평가와 지필평가 안내를 함께 확인합니다. 교사가 강조한 내용은 이해 여부를 점검할 단서이지만 출제를 보장하지는 않습니다. 출처를 알 수 없는 예상 문제보다 실제 수업 자료에서 빠진 부분을 먼저 찾으세요.'),
 ('할 일을 세 가지로 분류하기','혼자 설명하고 풀 수 있는 내용, 힌트를 보면 가능한 내용, 시작부터 막히는 내용으로 표시합니다. 곧 해결할 수 있는 빈칸을 먼저 채우고, 오래 걸리는 부분은 질문할 핵심을 적으세요. 어려운 한 문제에 남은 시간을 모두 쓰지 않도록 종료 기준도 정합니다.'),
 ('요약 노트를 꾸미기보다 확인에 쓰기','단원 제목을 보고 기억나는 개념을 적은 다음 교과서와 비교합니다. 국어는 답의 근거 문장, 영어는 헷갈린 문장 구조, 수학은 적용 조건을 짧게 남기세요. 정리한 내용을 다시 읽는 데서 끝내지 말고 자료를 덮은 뒤 설명하거나 기본 문제에 적용해 봅니다.'),
 ('문제 풀이와 질문 시간을 나누기','학교 평가 방식에 맞는 문제를 골라 시간 안에 풀어 보고 멈춘 이유를 기록합니다. 해설을 읽은 문제는 별도 표시해 혼자 다시 확인하세요. 정답을 외웠다면 숫자나 표현이 달라진 유사 문제로 적용 여부를 살펴볼 수 있습니다.'),
 ('시험 전날의 준비를 남겨두기','마지막 날에는 새 범위를 넓히기보다 이미 정한 확인 목록을 마무리합니다. 준비물과 등교 시간을 확인하고 평소 취침 흐름을 지키세요. 시험이 끝나면 이번에 미뤄진 범위를 다음 학습 계획에 옮겨, 급한 준비가 매번 반복되지 않도록 합니다.')],
 ('오늘의 우선순위 기록',['시험 범위와 자료 위치 적기','혼자 가능한 내용 / 도움이 필요한 내용 표시','오늘 끝낼 과제 두 가지와 멈출 시간 정하기','질문 한 가지와 다음 재풀이 날짜 남기기']),
 [('기출문제만 보면 될까요?','학교에서 안내한 범위와 수업 자료를 먼저 확인하세요. 이전 문제는 형식을 살피는 참고 자료이며 이번 출제 내용을 보장하지 않습니다.'),('모든 범위를 끝내지 못하면 어떻게 하나요?','확인할 수 있는 핵심 과제를 정하고, 남은 부분은 질문 목록으로 남기세요. 시험 후 기초 보완 계획에도 이어서 반영합니다.')])

add(2,'국어영어수학공부영역','국어·영어·수학 공부를 영역별로 나누는 방법',
 '국어의 읽기 근거, 영어의 문장·듣기, 수학의 개념·적용을 나누고 과목별 확인 과제를 정리합니다.',2,'초중고','국어·영어·수학',
 '국어·영어·수학을 모두 오래 공부했는데 무엇이 나아졌는지 말하기 어렵다면 과목 이름보다 실제 과제를 작게 나눠 보세요. 읽기, 설명하기, 적용하기 중 어느 단계가 막히는지에 따라 다음 공부가 달라집니다.',[
 ('국어: 모르는 말부터 구분하기','지문을 읽다 멈춘 문장을 골라 낯선 어휘와 문장 관계를 나눠 표시합니다. 뜻을 찾은 뒤 그 문장이 앞뒤 내용과 어떻게 이어지는지 말해 보세요. 긴 글을 무조건 많이 읽는 것보다 지금 이해하지 못한 문장 하나를 정확히 확인하는 과제를 만들 수 있습니다.'),
 ('국어: 답을 고른 근거 남기기','설명문은 중심 내용과 이유를, 문학은 인물의 말과 행동 또는 표현을 바탕으로 답을 확인합니다. 선택지가 그럴듯하다는 느낌과 글에 제시된 근거를 구분하세요. 틀린 문제에는 정답 번호보다 선택지를 판단한 이유를 남기는 편이 다음 읽기에 연결하기 쉽습니다.'),
 ('영어: 단어와 문장을 따로 확인하기','단어 뜻을 알아도 문장이 이해되지 않는다면 주어·동사와 수식 관계를 살펴봅니다. 반대로 구조는 보이는데 내용이 막히면 문맥에 맞는 단어 뜻을 확인하세요. 외운 단어를 예문에서 다시 쓰거나 해석해 보면서 어휘 공부와 읽기 과제를 연결합니다.'),
 ('영어: 듣기에서 놓친 지점 찾기','먼저 들은 내용을 적고 대본과 비교합니다. 모르는 표현인지, 아는 표현을 소리로 알아듣지 못한 것인지 구분하세요. 한 구간을 다시 듣고 의미를 확인한 뒤 전체 흐름으로 돌아갑니다. 듣기 시간만 늘리기보다 확인한 표현과 남은 질문을 기록합니다.'),
 ('수학: 공식의 조건과 예제를 함께 보기','공식 이름만 외우지 말고 어떤 상황에서 쓰는지 설명해 봅니다. 예제의 각 줄에서 왜 그 계산을 하는지 확인한 뒤 해설을 덮고 기본 문제를 풀어 보세요. 계산 실수, 조건 해석, 개념 선택이 서로 다른 문제라면 보완 과제도 나눠야 합니다.'),
 ('세 과목의 계획을 같은 기준으로 비교하기','완료 기준을 문제 수뿐 아니라 설명·적용 결과로 적습니다. 국어는 근거를 찾은 문항, 영어는 혼자 해석한 문장, 수학은 이유를 설명한 풀이를 남길 수 있습니다. 과목마다 같은 시간을 배정할 필요는 없으며 실제 소요 시간과 어려움을 보고 조정하세요.')],
 ('과목별 한 줄 점검',['국어: 답의 근거 문장을 찾았는가?','영어: 어휘·구조·소리 중 어디서 막혔는가?','수학: 개념 선택의 이유를 설명할 수 있는가?','다음 시간에 혼자 확인할 과제는 무엇인가?']),
 [('세 과목을 매일 모두 해야 하나요?','학교 일정과 과제량에 따라 달라집니다. 일주일 동안 필요한 영역이 빠지지 않는지 살피고, 하루에는 실행할 수 있는 과제를 정하세요.'),('문제집은 많이 준비할수록 좋나요?','지금 교재에서 막힌 영역을 먼저 확인하세요. 새 교재가 필요한지, 기존 교재의 특정 부분을 다시 공부하면 되는지 나눠 판단합니다.')])

add(3,'동기를돕는코칭질문','학습 동기를 돕는 코칭, 상담에서 확인할 질문',
 '학생의 목표 선택과 구체적인 피드백을 살피고, 학습코칭 상담에서 실제 지도 방식을 확인할 질문을 정리합니다.',3,'초중고','',
 '코칭이 잘 맞는지 알아보려면 칭찬이나 관리라는 말만 듣기보다 학생이 목표를 정하고 도움을 받는 과정을 살펴보세요. 상담에서 실제 기록 예시와 질문 방식을 확인하면 우리 아이에게 필요한 도움을 더 구체적으로 비교할 수 있습니다.',[
 ('학생이 어려움을 설명할 기회가 있는지','부모의 기대와 학생이 느끼는 어려움은 다를 수 있습니다. 최근 과제 하나를 놓고 어디서 막혔는지 학생에게 먼저 물어보세요. 과제량, 개념 이해, 시작하는 부담을 구분해서 듣는지 확인합니다. 대답이 짧다면 틀린 문제나 플래너 같은 자료를 함께 보는 방법도 있습니다.'),
 ('목표를 함께 정하는지','자기결정성이론은 학습 동기를 설명할 때 자율성·유능감·관계성을 다룹니다. 이를 상담에 적용해 볼 질문은 “학생이 선택할 수 있는 과제는 무엇인가요?”입니다. 모든 결정을 혼자 맡기기보다 가능한 선택지를 주고 이유를 듣는 방식부터 확인할 수 있습니다.'),
 ('작은 과제의 완료 기준이 있는지','“열심히 하기” 대신 “헷갈린 두 문장을 혼자 해석하고 근거 표시하기”처럼 결과를 볼 수 있는 과제를 정합니다. 너무 쉬운 과제만 반복하거나 학생이 감당하기 어려운 목표를 세우고 있지는 않은지 살피세요. 완료 여부와 실제 도움받은 정도를 함께 남기는지 질문합니다.'),
 ('피드백이 다음 행동으로 이어지는지','“잘했어”에 더해 어떤 풀이가 바뀌었는지 알려 주는 설명이 필요합니다. “조건을 먼저 표시해서 식을 세웠구나”처럼 구체적인 피드백 예시를 요청하세요. 틀린 경우에도 사람을 평가하는 말보다 다시 확인할 단계와 질문할 내용을 제시하는지 살펴봅니다.'),
 ('보상과 비교가 중심이 되지 않는지','점수나 선물만으로 공부를 설명하면 학생이 과제의 의미를 말하기 어려울 수 있습니다. 다른 학생과 순위를 비교하는 대신 본인의 이전 기록과 달라진 행동을 확인하는지 물어보세요. 포인트·행사·팀 활동 같은 운영은 지점마다 다르므로 실제 제공 여부를 별도로 확인합니다.'),
 ('상담 후 확인할 자료를 정하기','코칭이라는 이름만으로 성과를 예측할 수는 없습니다. 질문 기록, 과제 수정 과정, 혼자 다시 한 결과를 어떤 주기로 공유하는지 확인하세요. 수업을 시작한다면 학생이 부담을 느끼는 부분과 도움이 되는 부분을 함께 듣고, 필요할 때 계획을 조정할 기준도 정합니다.')],
 ('상담에 가져갈 질문',['학생이 목표를 선택하는 과정이 있나요?','미완료 과제의 원인을 어떻게 확인하나요?','피드백 후 혼자 다시 해 본 기록을 볼 수 있나요?','지점의 실제 관리 항목과 공유 주기는 어떻게 되나요?']),
 [('칭찬을 많이 하면 동기가 높아지나요?','학생이 어떤 행동을 잘했는지 이해할 수 있는 구체적인 설명이 중요합니다. 반응을 살피면서 학생에게 부담이 되는 평가나 비교는 줄여 보세요.'),('모든 지점에서 같은 코칭을 하나요?','공식 학습 방향과 개별 지점의 운영은 구분해야 합니다. 학년·과목·담당 지도 방식과 기록 공유 범위를 희망 지점에서 확인하세요.')],['motivation','wawa'])

add(4,'학원등록체크리스트','학원 등록 전 확인할 수업·교육비·통학 체크리스트',
 '학원 등록 전 수업 대상과 지도 방식, 교육비 구성, 통학 동선 및 상담에서 확인할 자료를 정리합니다.',4,'초중고','',
 '학원을 고를 때는 유명한 이름보다 우리 아이에게 필요한 도움과 실제 운영 조건을 나란히 놓고 비교해 보세요. 주소와 교육비 자료를 먼저 확인한 뒤, 학생의 과목·학년과 생활 일정에 맞는지 살펴보는 순서입니다.',[
 ('학원을 찾는 이유를 한 문장으로 쓰기','개념 설명이 필요한지, 혼자 복습하는 흐름을 만들고 싶은지, 학교 시험 자료를 정리해야 하는지 구분합니다. “성적을 올리고 싶다”는 목표만 적으면 수업을 비교하기 어렵습니다. 최근 어려웠던 과제와 집에서 도움받는 부분을 기록해 상담 자료로 준비하세요.'),
 ('학년·과목·현재 수준 확인하기','홈페이지에 과목 이름이 있어도 모든 학년이 등록 가능한 것은 아닙니다. 실제 개설 학년과 시작 교재, 학습 수준을 확인하는 방법을 물어보세요. 학교 진도와 학생이 이해한 진도가 다를 때 어느 부분부터 공부하는지도 확인해야 합니다.'),
 ('수업 중과 수업 후의 역할 나누기','설명, 질문, 독립 풀이, 복습을 어느 순서로 하는지 구체적으로 묻습니다. 숙제가 많은지보다 학생이 막혔을 때 받을 수 있는 도움과 재확인 과정을 살펴보세요. 담당 선생님과 학부모에게 공유하는 내용은 개인 정보를 가린 실제 예시로 확인할 수 있습니다.'),
 ('교육비는 같은 조건으로 비교하기','안내 금액 옆의 횟수와 시간을 함께 봅니다. 교재, AI 학습 등 별도 구성의 포함 여부도 확인하세요. 교육부는 학원 등록 정보와 교습비 등을 공개 서비스에서 확인하도록 안내합니다. 홈페이지 자료와 상담 견적의 조건이 다르면 최종 적용 조건을 다시 물어보세요.'),
 ('실제 등원 주소와 생활 시간을 보기','동네 이름과 건물 주소가 다를 수 있으므로 지점 안내의 주소·층을 확인합니다. 학교에서 이동하는 시간, 귀가 동선과 식사 시간을 함께 고려하세요. 수업 종료 시간만 비교하지 말고 귀가 후 숙제와 취침까지 가능한 일정을 적어 봅니다.'),
 ('등록 직전 안내 내용을 남기기','시간표, 교육비 구성, 결석 시 안내, 수업 변경과 환불에 관한 설명을 문서로 확인하세요. 운영 기간이나 홍보 문구만으로 수업 품질을 단정하지 않습니다. 학생이 수업을 시작한 뒤 어떤 자료로 적응 상황을 확인할지도 미리 질문해 두면 좋습니다.')],
 ('비교표에 적을 네 칸',['필요한 도움: 현재 막힌 과제와 질문','수업 조건: 학년·과목·횟수·시간','비용 조건: 기본 금액과 별도 항목','생활 조건: 이동·식사·귀가·복습 시간']),
 [('홈페이지 교육비가 최종 금액인가요?','자료에 표시된 수업 조건을 먼저 확인하세요. 선택 프로그램과 교재 등 포함 범위에 따라 달라질 수 있어 등록 전 최종 안내를 확인해야 합니다.'),('오래 운영한 학원이 더 좋은가요?','운영 기간만으로 판단하기 어렵습니다. 학생에게 필요한 지도와 실제 수업 구성, 질문·피드백 방식 등을 비교해 보세요.')],['fees'])

add(5,'시험기간수면관리','시험 기간 수면 관리, 공부와 취침 시간을 함께 계획하기',
 '연령별 수면 권장 범위와 생활 리듬을 살피고, 시험 기간 공부를 취침·기상 계획 안에 배치하는 방법을 정리합니다.',5,'초중고','',
 '시험 준비 시간이 부족하다고 수면부터 줄이면 공부 계획이 생활 전체와 어긋날 수 있습니다. 취침·기상 시간을 먼저 적고 그 안에서 오늘 확인할 과제를 선택해 보세요. 수면 시간에는 연령과 개인차를 함께 고려해야 합니다.',[
 ('학생에게 성인의 수면 기준을 적용하지 않기','CDC의 일반 권장 범위는 6~12세에 하루 9~12시간, 13~17세에 8~10시간입니다. 학생에게 일괄적으로 6~7시간이면 충분하다고 안내하기 어렵습니다. 이는 개인별 진단이 아니며 수면의 질과 낮 동안의 상태도 함께 살펴야 합니다.'),
 ('등교 시간에서 거꾸로 생활표 그리기','일어나야 하는 시간과 아침 준비 시간을 먼저 정합니다. 취침 준비, 귀가, 식사와 과제 시간을 앞쪽으로 배치하세요. 해야 할 일이 들어가지 않으면 잠을 없애기보다 오늘 과제의 범위를 줄이거나 도움을 요청할 부분을 정합니다.'),
 ('평소 리듬과 시험 일정의 차이 보기','시험 며칠 전부터 갑자기 늦게 자고 늦게 일어나는 계획을 세우지 않습니다. 평일과 쉬는 날의 취침·기상 차이가 큰지 기록해 보세요. 시험 전날에만 오래 잔다고 그동안의 생활이 모두 해결된다고 기대하기보다 지속 가능한 일정을 살핍니다.'),
 ('취침 직전의 환경을 정리하기','자기 전에 다음 날 자료와 준비물을 챙겨 걱정거리를 줄여 봅니다. 화면 사용과 카페인 섭취가 늦은 시간에 몰리지 않는지 확인하세요. 방의 소음·빛·온도도 살펴보고, 휴대전화 알림은 가족과 합의해 조정할 수 있습니다.'),
 ('졸림을 의지 부족으로만 해석하지 않기','책상에서 계속 졸거나 아침에 일어나기 어렵다면 실제 수면 기록을 먼저 확인합니다. 낮잠은 누구에게나 같은 길이가 맞는 것은 아니므로 밤 수면을 방해하는지 살펴보세요. 잠을 깨기 위해 무리하게 공부량이나 카페인을 늘리는 방식은 피합니다.'),
 ('계속되는 어려움은 함께 상담하기','잠들기 어렵거나 자주 깨는 일이 이어지고 낮의 생활에도 영향을 준다면 보호자와 함께 의료 전문가에게 상담할 수 있습니다. 공부 계획만으로 해결해야 할 문제라고 단정하지 마세요. 학습 상담에서는 과제량과 시간표를, 건강 상담에서는 수면 문제를 구분해 다룹니다.')],
 ('일주일 수면·공부 기록',['취침 시각 / 기상 시각 / 낮의 졸림 적기','잠들기 전 화면·카페인 사용 시간 확인','저녁 과제가 끝난 시각과 미완료 이유 기록','수면을 줄이지 않는 과제 조정 한 가지 선택']),
 [('시험 전날 밤을 새워도 괜찮을까요?','밤샘을 공부 계획의 기본 조건으로 삼지 마세요. 연령에 맞는 수면과 등교 일정을 고려해 확인할 범위를 줄이는 방향으로 준비합니다.'),('권장 시간만 채우면 충분한가요?','시간뿐 아니라 수면의 질과 낮 동안의 상태도 중요합니다. 지속적인 수면 어려움은 보호자와 함께 의료 전문가에게 상담해 주세요.')],['sleep'])

add(6,'내신계획역산','내신 대비 학습 계획, 학교 일정에서 역산하는 방법',
 '학교 평가 일정과 시험 범위를 바탕으로 준비·점검·보완 과제를 나누고, 주간 계획을 수정하는 방법을 정리합니다.',1,'중고','',
 '내신 계획은 공부할 날짜를 채우기 전에 학교가 무엇을 평가하는지 확인하는 데서 시작합니다. 시험 범위와 제출 과제가 정해진 자료를 모은 뒤, 개념 확인과 적용·보완을 일정 안에 나누어 배치해 보세요.',[
 ('학교 평가 안내를 기준으로 시작하기','지필평가 날짜와 범위, 수행평가 제출일과 기준을 학교 안내에서 확인합니다. 아직 확정되지 않은 범위는 임의로 적지 말고 확인할 날짜를 남기세요. 평가 방식과 반영 비율은 학교·학년·과목별 자료를 확인해야 하며 일반적인 설명으로 대신할 수 없습니다.'),
 ('교재와 수업 자료의 위치 정리하기','과목마다 교과서, 배부 자료, 노트와 온라인 과제를 한 목록에 적습니다. 같은 단원을 여러 교재에서 다룬다면 주로 확인할 자료와 보조 자료의 역할을 나누세요. 자료를 찾는 데 시간이 반복해서 들지 않도록 단원이나 날짜를 표시합니다.'),
 ('공부 범위를 완료 과제로 바꾸기','“수학 단원 공부” 대신 “예제의 이유 설명 후 기본 문제 혼자 풀기”처럼 적습니다. 영어는 학교 지문을 읽고 서술형에서 필요한 문장 조건을 확인하는 식입니다. 제출해야 하는 과제와 시험 전에 확인할 내용을 한꺼번에 묶지 말고 따로 표시하세요.'),
 ('시험일에서 준비 단계를 역산하기','마지막 확인 전에 혼자 풀어 보는 시간이 필요하고, 그 전에 개념과 예제를 살피는 시간이 필요합니다. 남은 일정 안에 이 순서를 넣되 과목마다 동일한 날짜 수를 강요하지 않습니다. 이해가 부족한 단원은 질문과 재확인 시간을 별도로 배치하세요.'),
 ('주간 계획에 빈칸 남기기','모든 시간을 과제로 채우면 학교 행사나 예상보다 긴 문제 하나에도 계획이 무너질 수 있습니다. 조정할 수 있는 칸을 남겨 두세요. 미완료 과제를 다음 날로 전부 옮기기보다 필수 제출, 핵심 개념, 추가 연습의 우선순위를 다시 정합니다.'),
 ('진도표와 혼자 한 결과를 함께 보기','교재를 어디까지 읽었는지와 혼자 해결할 수 있는지는 다릅니다. 주말에는 도움 없이 한 결과, 질문이 남은 부분, 다음에 확인할 문제를 살펴보세요. 과제량을 늘리는 결정은 실제 소요 시간과 학생이 감당할 생활 일정 안에서 내립니다.')],
 ('학교 일정 기반 계획 순서',['공식 평가 안내와 제출 날짜 모으기','범위를 개념 확인·혼자 적용·보완으로 나누기','남은 주간 일정에 과제와 질문 시간 넣기','주말에 완료 결과를 보고 다음 주 조정']),
 [('시험 범위가 아직 안 나왔어요.','진행 중인 수업 자료를 정리하고 지금 배운 내용을 확인하세요. 범위가 발표되면 목록을 갱신하며 미확정 내용을 확정 사실처럼 적지 않습니다.'),('계획보다 진도가 느리면 시간을 늘려야 하나요?','개념이나 문제 읽기 중 어디에서 시간이 걸렸는지 확인하세요. 우선 과제와 도움받을 부분을 조정한 뒤 생활 일정 안에서 시간을 배정합니다.')])

add(7,'방학스케줄과제','방학 공부 스케줄, 생활시간 안에서 실행할 과제 정하기',
 '방학의 생활 일정과 공부 목표를 연결하고, 하루 과제·휴식·주간 점검을 포함한 스케줄을 만드는 방법을 정리합니다.',1,'초중고','',
 '방학 계획표에 긴 공부 시간을 적기 전에 식사와 수면, 등원, 가족 일정부터 넣어 보세요. 남는 시간에 실행할 과제를 정하면 계획을 실제 생활에 맞게 고칠 수 있습니다. 복습과 예습의 역할도 구분해서 시작합니다.',[
 ('방학 동안 바꾸고 싶은 한 가지 고르기','지난 학기에서 어려웠던 개념, 미뤄진 독서, 혼자 시작하는 습관 중 우선 목표를 고릅니다. “전 과목 완성”처럼 범위가 넓으면 오늘 할 일이 보이지 않습니다. 무엇을 혼자 설명하거나 적용하게 될지 완료 장면을 적어 보세요.'),
 ('고정 일정과 자유 시간을 나누기','가족 여행, 학원, 식사, 기상·취침을 먼저 표시합니다. 남은 시간은 날짜마다 다를 수 있으므로 모든 요일을 같은 표로 채우지 않습니다. 이동 후 바로 긴 공부를 배치해야 하는지, 준비와 쉬는 시간이 필요한지도 함께 확인하세요.'),
 ('복습과 예습의 우선순위 정하기','현재 막힌 개념이 다음 단원에 연결된다면 복습을 먼저 선택할 수 있습니다. 예습은 교재 진도를 많이 넘기는 목적보다 낯선 말과 기본 예제를 확인하는 정도로 시작해 보세요. 학생이 혼자 할 수 있는 범위와 설명을 요청할 부분을 나눕니다.'),
 ('시간 칸에 구체적인 과제 넣기','“오전 수학” 대신 단원·자료·완료 기준을 씁니다. 처음에는 실제 소요 시간을 재 보고 다음 일정에 반영하세요. 집중과 휴식의 길이에 유일한 정답은 없습니다. 긴 블록에서 자꾸 멈춘다면 과제를 더 작게 나누고 짧은 쉼을 사이에 배치합니다.'),
 ('빠진 날을 복구하는 칸 만들기','몸이 피곤하거나 외부 일정이 길어진 날에는 최소 과제만 남길 수 있습니다. 미완료 항목을 다음 날에 모두 쌓지 말고 주간 조정 칸에서 고르세요. 하루의 실패를 방학 전체의 실패로 판단하지 않도록 다음 시작 과제를 따로 적습니다.'),
 ('개학 전 생활 흐름도 준비하기','방학 끝에는 학교 준비와 일상 일정도 돌아옵니다. 공부 진도만 보고 계획을 마무리하지 말고 등교 준비, 과제 제출과 취침 흐름을 함께 살펴보세요. 방학에 확인한 약점과 질문을 다음 학기 수업 또는 상담에서 활용할 기록으로 남깁니다.')],
 ('하루 스케줄을 적는 네 줄',['오늘의 고정 일정과 공부 가능한 칸','교재·범위·완료 기준이 있는 우선 과제','휴식과 예상 밖 일정에 쓸 조정 칸','실제 걸린 시간과 다음에 바꿀 한 가지']),
 [('복습과 선행 중 무엇을 먼저 할까요?','현재 막힌 기초와 다음 학습의 연결을 살펴보세요. 혼자 적용하지 못하는 개념이 있다면 복습 과제를 먼저 정하고 예습 범위를 조절할 수 있습니다.'),('계획표를 매일 새로 써야 하나요?','고정 일정은 주간 표로 두고 하루 과제와 결과만 갱신해도 됩니다. 작성 시간이 실제 공부를 대신하지 않도록 필요한 항목만 남기세요.')])

add(8,'시험후공부재시작','중간고사 후 공부 의욕이 떨어졌을 때 다시 시작하는 방법',
 '중간고사 후의 피로와 부담을 구분하고, 학생과의 대화·작은 시작 과제·일상 회복을 정리합니다.',0,'중고','',
 '시험을 마친 뒤 바로 다음 목표를 정하기 어려운 학생도 있습니다. 쉬어야 하는 피로와 결과에 대한 실망, 다음에 무엇을 할지 모르는 상태를 구분해 보세요. 이번 글은 점수 분석보다 공부를 다시 시작할 준비에 초점을 맞춥니다.',[
 ('시험 직후의 상태를 먼저 듣기','“왜 또 안 하니?”보다 “시험 준비에서 가장 힘들었던 게 뭐였어?”라고 물어봅니다. 잠이 부족했는지, 기대한 결과가 나오지 않아 속상한지, 다음 과제가 막막한지 들어 보세요. 대답을 바로 고치기보다 학생이 말한 사실과 감정을 먼저 확인합니다.'),
 ('휴식에도 범위를 정하기','쉬는 동안 모든 일정을 없애야 하는 것은 아닙니다. 식사와 수면 같은 일상은 유지하고, 쉬고 싶은 활동과 다시 시작할 시점을 함께 정할 수 있습니다. 휴식 이후 과제를 한꺼번에 몰아 넣지 않도록 다음 날의 작은 시작까지 준비하세요.'),
 ('점수와 사람에 대한 평가를 분리하기','결과가 아쉽다는 것과 학생의 가치가 낮다는 것은 다른 말입니다. 비교나 단정 대신 시험 전 실제 했던 과제와 힘들었던 과정을 다룹니다. 원인을 분석하는 대화는 학생이 준비됐을 때 시험지 같은 자료를 놓고 진행할 수 있습니다.'),
 ('익숙하고 끝이 보이는 과제부터 선택하기','바로 어려운 문제집을 늘리기보다 이미 배운 예제 한 개, 짧은 지문 하나처럼 완료를 확인할 과제를 정합니다. 학생이 선택할 두 가지 과제를 제시하는 방법도 있습니다. 시작이 됐는지와 어느 정도 도움받았는지를 기록하고 다음 범위를 조절하세요.'),
 ('공부를 멈추게 하는 조건 바꾸기','책상에 자료가 없는지, 과제가 너무 커 보이는지, 알림 때문에 흐름이 끊기는지 살펴봅니다. 의욕을 기다리는 대신 자료를 펴고 첫 질문을 적는 행동으로 시작할 수 있습니다. 어려운 부분에서 멈춘다면 도움을 청할 방법도 미리 정하세요.'),
 ('다음 주의 기준을 작게 잡기','며칠 동안의 집중 시간만으로 회복을 판단하지 않습니다. 시작 약속을 지켰는지, 질문을 했는지, 혼자 끝낸 과제가 있는지 봅니다. 부담이나 어려움이 지속돼 학교와 일상에도 영향을 주면 보호자·학교 상담 담당자와 함께 상황을 살펴볼 수 있습니다.')],
 ('시험 후 대화 예시',['이번 시험에서 가장 피곤했던 일은 무엇이었어?','쉬고 난 뒤 먼저 해볼 과제를 둘 중 골라볼까?','혼자 시작하기 어려운 부분은 어디였어?','다음 주에는 어떤 약속 하나를 확인하면 좋을까?']),
 [('시험 다음 날부터 바로 공부해야 하나요?','학생의 피로와 남은 학교 일정을 함께 고려하세요. 쉬는 시간과 다시 시작할 작은 과제를 합의하는 방식으로 생활 흐름을 이어갈 수 있습니다.'),('점수 이야기를 아예 하지 않아야 하나요?','점수를 숨기기보다 대화의 시점과 방식을 조정하세요. 감정과 사실을 구분하고 학생이 준비됐을 때 자료를 놓고 다음 행동을 정합니다.')])

add(9,'시험컨디션점검','기말고사 컨디션 관리, 식사·휴식·공부량 점검하기',
 '기말고사 준비 중 식사·휴식·이동·과제량을 함께 살피고, 시험 전날과 당일의 준비 항목을 정리합니다.',5,'중고','',
 '시험 기간의 컨디션은 특정 음식이나 마지막 하루의 노력만으로 정해지지 않습니다. 평소 생활에 공부량이 들어맞는지부터 확인해 보세요. 식사, 쉬는 시간, 이동과 준비물을 계획에 넣으면 빠뜨린 부담을 찾기 쉽습니다.',[
 ('하루 과제가 생활 시간을 넘는지 보기','수업과 등원 뒤 귀가·식사·취침까지 남는 시간을 적습니다. 계획이 계속 밀린다면 생활을 없애기보다 공부할 범위를 다시 정하세요. 오래 앉아 있었다는 기록과 실제 완료 과제를 나란히 놓으면 과제량을 조절할 단서를 찾을 수 있습니다.'),
 ('식사를 공부와 경쟁시키지 않기','문제를 더 풀려고 끼니를 계속 미루는 일정인지 확인합니다. 평소 먹는 식사를 무리 없이 챙길 시간을 두세요. 특정 영양소나 보충제가 시험 점수를 높인다고 단정할 수는 없습니다. 몸에 맞지 않는 음식이나 익숙하지 않은 방식으로 시험 직전 생활을 크게 바꾸지 않습니다.'),
 ('쉬는 시간에 무엇을 할지 정하기','휴식이 끝없이 늘어나는 경우 시작과 끝을 약속할 수 있습니다. 반대로 쉬는 시간을 전혀 두지 않고 공부를 이어가는 계획도 점검하세요. 가볍게 몸을 움직이거나 자리를 정리하는 활동처럼 본인이 편안하게 할 수 있는 방식을 선택합니다.'),
 ('준비물과 이동의 부담 줄이기','시험 전날에는 필기구, 학교에서 안내한 준비물과 등교 동선을 확인합니다. 아침에 자료를 찾느라 바쁘지 않도록 마지막 확인용 목록을 따로 두세요. 시험 과목과 교실 등 실제 학교 안내를 기준으로 준비하며 일반적인 시험 요령을 그대로 적용하지 않습니다.'),
 ('몸의 불편함을 무조건 참지 않기','두통이나 피로 등 불편함이 있다면 학생이 말할 수 있도록 듣습니다. 학습량 조정으로 해결될 것이라고 단정하지 마세요. 계속되거나 일상에 영향을 주는 문제는 보호자와 함께 적절한 의료 상담을 고려할 수 있습니다. 학습 기록에는 공부 중 불편했던 상황을 사실대로 남깁니다.'),
 ('시험 후에도 회복할 일정 남기기','시험이 끝나면 남은 과제와 쉬는 시간을 함께 살펴봅니다. 전 과목의 오답 정리를 바로 몰아 하기보다 확인할 순서를 나누세요. 다음 시험 계획에서는 부족했던 식사·휴식·준비 시간을 반영해 같은 과부하가 반복되지 않도록 합니다.')],
 ('전날과 당일의 확인 목록',['학교가 안내한 준비물·시간·장소 확인','아침 준비와 식사 시간을 일정에 넣기','마지막 확인 자료를 작은 목록으로 묶기','불편한 상태가 있으면 보호자에게 알리기']),
 [('시험 기간에는 운동을 꼭 해야 하나요?','누구에게나 같은 운동량을 요구할 필요는 없습니다. 몸 상태와 기존 생활에 맞는 가벼운 활동과 쉬는 시간을 선택하세요.'),('시험 직전에 좋은 음식을 챙기면 충분한가요?','특정 음식의 효과를 기대하기보다 평소 식사와 생활 일정을 살펴보세요. 건강 상태에 따른 식사 문제는 보호자와 전문가에게 확인합니다.')])

add(10,'수업과자기주도연결','학원 수업과 자기주도학습을 연결하는 방법',
 '학원 수업과 집에서의 독립 학습 역할을 나누고, 질문·재풀이·다음 수업 피드백을 연결하는 방법을 정리합니다.',4,'초중고','',
 '수업 시간에 이해했다는 느낌과 혼자 다시 할 수 있는 상태는 다를 수 있습니다. 학원에서 받은 설명을 집의 과제로 옮기고, 혼자 해 본 결과를 다음 수업에 가져오는 흐름을 만들어 보세요.',[
 ('수업에서 도움받을 부분을 고르기','개념 설명, 풀이 방향, 과제 우선순위처럼 필요한 도움을 구체적으로 적습니다. 선생님이 모든 과제를 대신 결정하는 방식이 학생에게 필요한지 살펴보세요. 학생이 선택할 부분과 안내가 필요한 부분을 나누면 수업의 역할을 비교하기 쉽습니다.'),
 ('질문 전에 시도한 내용을 남기기','모르는 문제에는 답만 묻기보다 조건을 읽고 해 본 풀이와 멈춘 줄을 표시합니다. “식은 세웠지만 이 변형이 이해되지 않는다”처럼 질문하면 필요한 설명의 범위가 드러납니다. 시작부터 막힌 경우도 숨기지 말고 어떤 말이나 개념이 낯선지 적어 보세요.'),
 ('설명을 들은 직후 혼자 확인하기','도움받은 풀이를 옮겨 적은 뒤 끝내기보다 해설을 덮고 핵심 과정을 설명합니다. 어려운 문제의 정답만 기억했다면 기본 예제에서 다시 적용해 볼 수 있습니다. 수업에서 독립 확인 시간을 어떻게 두는지는 실제 지점 운영을 물어보세요.'),
 ('집에서는 작은 재확인 과제 정하기','숙제 전체 외에 오늘 불확실했던 한 부분을 선택할 수 있습니다. 그 과제를 혼자 한 결과와 남은 질문을 구분해 기록하세요. 집에서 부모가 대신 풀이를 설명해 준 경우도 표시하면 다음 지도에서 도움의 정도를 파악하기 쉽습니다.'),
 ('다음 수업에 결과를 돌려주기','완료 표시만 보여 주기보다 어느 문제를 혼자 풀었고 어디서 다시 막혔는지 가져갑니다. 같은 실수가 반복되는지, 다른 표현에서는 적용이 어려운지 확인하세요. 피드백을 받은 뒤에는 과제를 더 늘릴지, 기초로 돌아갈지 다음 행동을 정합니다.'),
 ('학생이 맡는 역할을 서서히 늘리기','학년에 따라 역할을 일괄 지정하기보다 현재 가능한 수준을 봅니다. 자료 준비, 첫 과제 선택, 결과 기록 중 하나부터 맡길 수 있습니다. 혼자 한다는 의미를 도움 없이 버틴다는 뜻으로 해석하지 말고 필요한 질문을 하는 능력도 함께 살펴보세요.')],
 ('수업과 집을 잇는 기록',['수업에서 질문한 부분과 받은 힌트','집에서 혼자 다시 해 본 과제와 결과','도움받은 경우 그 내용과 남은 질문','다음 수업에서 확인할 개념 한 가지']),
 [('학원에 다니면 자기주도학습이 어려워지나요?','수업의 존재보다 학생이 맡는 역할과 독립 확인 과정이 중요합니다. 설명을 받은 뒤 혼자 시도하고 결과를 피드백에 연결하는 흐름을 살펴보세요.'),('집에서 부모가 꼭 가르쳐야 하나요?','자료와 시간 준비를 돕되 학생이 막힌 지점을 먼저 듣습니다. 직접 풀이를 대신하기보다 다음 수업에 질문할 내용을 정리하도록 도울 수 있습니다.')])

add(11,'학기중학습스트레스','2학기 학습 스트레스, 과제와 생활 부담을 나눠 살피기',
 '2학기의 과제·학교 일정과 생활 부담을 구분하고, 가족 대화와 도움 요청으로 조정할 부분을 정리합니다.',5,'초중고','',
 '학기 중에 공부가 버겁다는 말을 들으면 의지부터 평가하기보다 실제 일정과 부담을 함께 살펴보세요. 학습 계획을 조정할 부분과 정서적인 지원이 필요한 부분을 나누는 것이 중요합니다.',[
 ('부담이 생긴 장면을 구체적으로 듣기','어느 시간과 과제에서 힘들었는지 학생에게 묻습니다. 숙제가 끝나지 않은 상황, 발표를 앞둔 걱정, 친구와의 비교는 서로 다른 문제일 수 있습니다. 대답을 하나의 원인으로 정리하려 하지 말고 학생이 말한 상황과 필요한 도움을 나란히 적어 보세요.'),
 ('과제량을 실제 시간으로 확인하기','학교·등원·이동·식사 뒤 남는 시간에 과제가 들어가는지 확인합니다. 과제를 빨리 끝내라는 말만으로 부족한 시간을 만들 수는 없습니다. 제출 기한, 혼자 가능한 범위와 질문이 필요한 부분을 나눠 오늘 할 양을 조정하세요.'),
 ('결과와 비교에 관한 말을 살피기','“다른 아이는 벌써 끝냈다”는 말이 부담을 더하는지 들어 봅니다. 점수에 대한 기대와 학생의 현재 어려움을 구분해 이야기하세요. 비교를 없애는 대신 목표를 흐리게 만들 필요는 없습니다. 학생의 이전 기록과 지금 할 수 있는 행동을 기준으로 대화를 바꿔 볼 수 있습니다.'),
 ('일상에서 조정할 작은 조건 고르기','식사와 수면, 쉬는 시간, 취미나 가족 일정이 계속 밀리는지 살핍니다. 한꺼번에 모든 생활을 바꾸기보다 미완료 과제 하나를 나누거나 이동 뒤 쉬는 시간을 두는 식으로 시작하세요. 휴식을 특정 길이로 정하면 스트레스가 해결된다고 단정하지 않습니다.'),
 ('부모와 학생의 역할을 합의하기','부모는 일정 확인이나 상담 자료 준비를, 학생은 어려운 과제와 질문 표시를 맡는 방식으로 정할 수 있습니다. 매일 여러 번 점검하기보다 함께 보기로 한 시간에 확인하세요. 기록이 감시처럼 느껴진다면 항목과 공유 범위를 다시 논의합니다.'),
 ('어려움이 이어지면 도움을 연결하기','불안이나 부담이 지속돼 학교와 일상에 영향을 주면 보호자·학교 상담 담당자에게 알릴 수 있습니다. 청소년상담1388은 청소년과 보호자가 이용할 수 있는 상담 안내를 제공합니다. 학습 상담이 건강이나 정서 문제의 전문적인 상담을 모두 대신하지는 않습니다.')],
 ('부담을 나누어 적는 목록',['학습: 과제 범위·난도·제출 기한','생활: 수면·식사·이동·쉬는 시간','관계: 비교·기대·도움 요청의 어려움','이번 주 조정 한 가지와 함께할 사람']),
 [('스트레스를 느끼면 공부를 전부 쉬어야 하나요?','부담의 원인과 정도에 따라 달라집니다. 생활에 필요한 시간을 확보하고 과제를 조정하되, 지속적인 어려움은 보호자와 상담 담당자에게 함께 알려 주세요.'),('아이가 설명을 잘 하지 않아요.','최근 힘들었던 과제나 하루 일정 하나를 함께 보며 시작하세요. 대답을 재촉하거나 원인을 단정하기보다 말할 시간을 주고 도움받을 방법을 제안합니다.')],['support'])

add(12,'개념기초다시연결','개념 이해가 막힐 때 기초를 다시 연결하는 방법',
 '개념을 이해하기 어려운 지점을 어휘·이전 개념·예제·적용으로 나누고, 기초를 확인할 과제를 정리합니다.',2,'초중고','국어·영어·수학',
 '설명을 여러 번 들어도 이해가 어려운 경우가 있다고 해서 학생을 느리다고 단정할 필요는 없습니다. 어떤 말이나 단계에서 연결이 끊기는지 확인하면 다시 살필 기초가 구체적으로 보입니다.',[
 ('먼저 문제의 말을 이해했는지 보기','질문이 무엇을 요구하는지 학생의 말로 바꿔 보게 합니다. 계산을 못한 것과 문제 문장을 이해하지 못한 것은 다른 상황입니다. 모르는 용어를 표시하고 쉬운 예로 설명한 뒤 원래 문장에 다시 적용해 보세요. 낯선 말이 많으면 과제의 범위를 줄입니다.'),
 ('이전 개념을 한 단계씩 확인하기','어려운 단원을 처음부터 전부 다시 공부하기보다 연결되는 개념을 찾아봅니다. 분수 덧셈이 막혔다면 분모가 무엇을 뜻하는지, 같은 크기의 조각으로 바꾸는 이유를 차례로 확인할 수 있습니다. 지금 어려운 문제와 직접 이어지는 부분부터 시작하세요.'),
 ('구체적인 예와 기호를 연결하기','그림이나 작은 수의 예를 이용해 개념을 설명한 뒤 같은 상황을 식이나 용어로 표현합니다. 그림만 이해하고 기호로 옮기지 못하는지, 기호는 쓰지만 의미를 설명하지 못하는지 나눠 보세요. 예시를 바꾸었을 때도 설명이 이어지는지가 확인할 지점입니다.'),
 ('풀이를 작은 단계로 나누기','해설 전체를 한 번에 따라 쓰지 말고 지금 줄이 앞의 줄에서 어떻게 나왔는지 확인합니다. 첫 단계만 혼자 하고 다음 단계는 힌트를 받는 방식으로 범위를 조절할 수 있습니다. 도움을 받은 부분에는 표시를 남겨 다음 재확인에서 구분하세요.'),
 ('바로 다른 문제로 적용해 보기','설명 직후에는 알겠다고 느껴도 혼자 적용하면 다시 막힐 수 있습니다. 처음에는 조건이 크게 달라지지 않은 기본 예제를 골라 보세요. 틀린 결과는 개념 선택, 읽기, 계산 중 무엇을 다시 확인할지 정하는 자료로 사용합니다.'),
 ('질문 자료를 모아 도움 요청하기','반복해서 막히는 말, 혼자 가능한 단계, 도움받은 부분을 선생님에게 보여 줍니다. “기초가 부족해요”보다 어떤 예제에서 멈췄는지 전달하면 확인할 범위가 좁아집니다. 이 기록만으로 학습 능력이나 개인의 특성을 진단하지 말고 필요한 지도를 상담하세요.')],
 ('기초 연결 기록 예시',['막힌 문제: 분모가 다른 분수의 덧셈','확인할 말: 분모·분자·같은 크기의 조각','혼자 해 볼 일: 그림을 같은 분모의 식으로 바꾸기','재확인: 숫자가 달라진 기본 문제 설명하기']),
 [('이해가 안 되면 더 쉬운 교재로 바꿔야 하나요?','먼저 어디에서 막혔는지 확인하세요. 현재 교재의 예제나 이전 단원을 살피면 되는지, 다른 설명 자료가 필요한지 구분한 뒤 선택합니다.'),('설명을 여러 번 들으면 해결될까요?','같은 설명의 횟수보다 막힌 단계와 적용 결과를 살펴보세요. 용어·예시·풀이 단계를 나누고 혼자 해 본 결과로 다음 도움을 정합니다.')])

add(13,'학습센터프로그램비교','학습센터 프로그램 비교, 필요한 도움부터 정하는 방법',
 '수업·코칭·학습 도구의 역할을 구분하고, 학생의 필요에 맞춰 프로그램 구성과 운영 조건을 비교합니다.',4,'초중고','',
 '프로그램 이름만 비교하면 어떤 도움이 필요한지 판단하기 어렵습니다. 학생이 막힌 과제를 먼저 적고, 설명·계획·피드백·학습 도구 중 어디에서 지원이 필요한지 나눠 보세요.',[
 ('비교 전에 현재 과제 하나 고르기','수학 예제를 혼자 시작하지 못하는지, 영어 단어를 외운 뒤 문장에서 놓치는지, 여러 숙제의 순서를 정하기 어려운지 기록합니다. 문제의 종류가 다르면 필요한 지원도 달라집니다. 효과가 좋다는 소개 문구보다 그 과제를 어떻게 다루는지 질문하세요.'),
 ('교과 수업이 맡는 부분 확인하기','개념을 설명하는 방식, 학생별 진도 조정과 질문 시간을 확인합니다. 학생이 이미 아는 단원과 어려운 단원을 어떻게 나누는지 물어보세요. 공식 브랜드 안내가 있어도 해당 지점의 실제 학년·과목·시간표가 같은지는 따로 확인해야 합니다.'),
 ('계획 관리가 무엇을 확인하는지 보기','플래너를 쓰게 한다는 말에서 한 걸음 더 나아가 실제 공부와 계획을 누가 비교하는지 확인합니다. 미완료 과제를 다음 날에 옮기기만 하는지, 원인과 양을 조정하는지 물어보세요. 학생이 계획을 선택하거나 수정할 수 있는 역할도 살펴봅니다.'),
 ('피드백 이후의 과제까지 질문하기','오답을 설명해 준 뒤 학생이 혼자 다시 확인하는 과정이 있는지 살펴봅니다. 기록에는 도움받은 풀이와 독립 풀이가 구분되는지 확인하세요. 프로그램별 효과를 점수로 단순 비교하기보다 실제 어떤 자료를 남기고 다음 수업에 반영하는지 보는 방법입니다.'),
 ('AI와 자료의 역할을 구분하기','AI 진단이나 문제 추천은 학습을 돕는 도구로 볼 수 있습니다. 결과를 해석하고 학교 진도와 연결하는 과정은 담당 지도 방식에 따라 달라질 수 있습니다. 도입 여부, 대상 과목과 비용을 확인하고 도구의 이름만으로 학습 효과를 보장받는다고 생각하지 않습니다.'),
 ('같은 조건으로 비용과 생활을 비교하기','수업 횟수·시간과 추가 구성의 포함 여부를 같은 칸에 적습니다. 통학과 집에서 해야 할 과제가 학생의 일상에 들어가는지도 확인하세요. 선택 후에는 실제 질문·과제 조정 기록을 보면서 필요한 도움을 받고 있는지 다시 살펴봅니다.')],
 ('프로그램 비교에 쓸 네 질문',['개념 설명과 질문은 어떻게 진행하나요?','계획과 실제 공부를 어떻게 비교하나요?','오답 피드백 후 혼자 확인할 기회가 있나요?','도구·교재·추가 관리의 포함 조건은 무엇인가요?']),
 [('AI 프로그램이 있으면 더 좋은가요?','학생에게 필요한 과제와 결과를 수업에 연결하는 방식을 먼저 확인하세요. 도구의 유무만으로 프로그램의 적합성을 판단하기 어렵습니다.'),('프로그램 효과를 어떻게 비교하나요?','학생의 필요와 실제 수업 구성을 같은 기준으로 비교하세요. 공개된 이름이나 사례만으로 모든 학생에게 같은 효과가 있다고 단정하지 않습니다.')],['wawa'])

add(14,'수능후형제공부시간','수능을 마친 형제자매와 공부 시간을 조율하는 방법',
 '수능을 마친 형제자매와 재학생의 다른 일정을 살피고, 공간·소음·기기 사용과 가족 약속을 정리합니다.',5,'중고','',
 '수능을 마친 가족과 아직 학교 시험을 준비하는 학생은 하루의 흐름이 다를 수 있습니다. 누군가를 방해하는 사람으로 정하기보다 각자 필요한 시간과 공간을 구체적으로 합의해 보세요.',[
 ('가족의 일정을 한 표에 놓기','수능 이후의 실제 일정과 재학생의 시험·수행평가·등원 일정을 함께 적습니다. 형제자매가 여유로워 보인다는 이유로 모두 같은 생활을 해야 한다고 정하지 않습니다. 어떤 시간에 조용한 공부가 필요한지 학생이 직접 설명하도록 도와주세요.'),
 ('공용 공간의 사용 시간을 정하기','식탁이나 거실에서 공부한다면 게임·영상·대화와 시간이 겹치는지 확인합니다. 가능한 별도 장소가 없다면 중요한 과제 시간에 어떤 활동을 다른 곳에서 할지 합의할 수 있습니다. 공간을 일방적으로 빼앗기보다 시작과 끝이 있는 약속으로 정합니다.'),
 ('소음과 기기 사용의 기준 만들기','“조용히 해”보다 통화·영상 소리·알림 중 어떤 부분이 불편한지 말합니다. 이어폰이나 다른 방을 쓰는 방법을 가족 상황에 맞춰 선택하세요. 휴대전화 약속도 재학생만 처벌하듯 정하지 말고 공동 공간과 공부 시간에 필요한 규칙을 함께 정합니다.'),
 ('자신의 학교 마감부터 확인하기','다른 가족의 휴식이 부럽다면 지금 자신의 제출일과 시험 준비 과제를 적어 봅니다. 먼 성적 목표만 반복하기보다 오늘 끝낼 범위와 끝난 뒤 쉬는 활동을 정하세요. 해야 할 일을 전부 끝낼 때까지 가족 활동을 못 한다는 식의 과도한 조건은 조정합니다.'),
 ('형제자매의 도움은 선택해서 받기','경험을 물어볼 수 있지만 같은 학교·과목에서도 평가와 자료가 달라질 수 있습니다. 과거의 방식이 지금 학생에게 그대로 맞는다고 단정하지 않습니다. 필요한 조언을 듣고 최종 시험 범위와 제출 기준은 현재 학교 안내에서 확인하세요.'),
 ('가족 약속을 실행 후 고치기','며칠 사용한 뒤 불편했던 시간과 잘 지켜진 약속을 다시 봅니다. 재학생의 계획이 너무 넓었는지, 공용 공간 약속이 모호했는지 확인하세요. 비교하는 대화보다 다음에 조정할 한 가지를 정하면 서로의 휴식과 공부를 함께 지킬 여지가 생깁니다.')],
 ('가족이 합의할 항목',['재학생에게 필요한 조용한 시간과 과제','공용 공간·통화·영상 소리의 약속','수능 이후 가족 일정과 함께 쉬는 시간','약속을 다시 확인할 날짜와 조정 한 가지']),
 [('형제자매가 쉬면 동생 공부가 꼭 흔들리나요?','가족마다 상황이 다릅니다. 영향을 미리 단정하지 말고 실제 불편한 시간·소음·과제 상황을 학생에게 듣고 조정하세요.'),('공부 경험이 있는 형제에게 지도를 맡겨도 되나요?','학생이 원하는 도움의 범위를 먼저 정하세요. 조언은 참고하되 학교의 현재 안내와 담당 선생님의 설명을 함께 확인합니다.')])

add(15,'기말고사범위정리','기말고사 시험 범위, 교과서·수업 자료를 한눈에 정리하기',
 '기말고사 범위를 교과서·배부 자료·평가 안내로 정리하고, 단원별 이해와 적용 상태를 점검하는 표를 만듭니다.',0,'중고','',
 '시험 공부를 시작하려는데 자료가 흩어져 있다면 범위표부터 만들어 보세요. 이 글은 공부 시간을 배정하기 전 단계인 자료 확인과 범위 정리에 초점을 맞춥니다. 무엇을 놓쳤는지 찾을 수 있는 목록이 목표입니다.',[
 ('확정된 학교 안내 모으기','과목별 시험 범위와 평가 안내를 학교에서 받은 자료로 확인합니다. 친구에게 들은 말과 실제 공지를 구분하세요. 범위가 변경되면 이전 기록을 그대로 두지 말고 바뀐 날짜와 내용을 표시합니다. 확정되지 않은 항목은 확인 필요로 남깁니다.'),
 ('교과서 쪽수와 단원 이름 함께 적기','쪽수만 적으면 무엇을 공부하는지 떠올리기 어려울 수 있습니다. 단원과 핵심 개념을 나란히 적고, 제외되는 자료가 있는지도 확인하세요. 과목마다 교과서 외 자료가 평가에 연결되는지 실제 안내에서 살펴봅니다.'),
 ('배부 자료와 노트의 연결 표시하기','자료마다 관련 단원과 수업 날짜를 붙입니다. 교과서에서 읽은 내용과 배부 문제·필기가 어디에서 이어지는지 표시하세요. 빠진 자료가 있다면 임의로 내용을 추정하기보다 담당 선생님이나 학교 안내에서 확보할 방법을 확인합니다.'),
 ('수행평가 일정과 지필 범위 구분하기','제출 과제와 시험 범위를 같은 표시로 두면 놓치기 쉽습니다. 수행평가는 날짜·제출 방식·평가 기준을 별도 칸에 적으세요. 이미 제출한 것과 준비 중인 것을 구분하면 지필평가 공부와 겹치는 주의 과제량을 조정할 수 있습니다.'),
 ('이해와 적용 상태를 따로 표시하기','읽어 본 단원이라는 표시만으로 끝내지 않습니다. 개념을 설명할 수 있는지, 기본 문제를 혼자 해결할 수 있는지 각각 표시하세요. “봤음”과 “혼자 했음”이 다르면 재확인 과제가 필요합니다. 질문이 남은 자료에는 질문할 문장이나 문제 번호를 적습니다.'),
 ('범위표를 실제 공부 목록으로 옮기기','자료 확인이 끝나면 부족한 항목을 오늘의 작은 과제로 바꿉니다. 표시를 예쁘게 만드는 데 시간을 쓰기보다 자료 위치와 다음 행동이 보이도록 정리하세요. 강조 표시나 이전 기출 유형은 참고 단서이며 이번 출제를 보장하는 예측으로 사용하지 않습니다.')],
 ('범위표에 필요한 칸',['과목 / 단원 / 교과서 쪽수','연결 자료 / 제외 항목 / 확인 필요','개념 설명 / 혼자 적용 / 남은 질문','다음 확인 과제와 자료 위치']),
 [('교과서만 정리하면 충분할까요?','학교에서 안내한 자료와 평가 범위를 확인하세요. 배부 자료나 별도 과제가 있다면 교과서 단원과 연결해서 목록에 포함합니다.'),('범위를 모두 읽으면 완료로 표시하나요?','읽기와 독립 적용을 나누어 표시하세요. 설명하거나 풀어 본 결과를 기준으로 다음에 확인할 부분을 정합니다.')])

add(16,'과목별시간배분','과목별 공부 시간 배분, 완료한 과제로 조정하는 방법',
 '과목별 과제의 실제 소요 시간과 어려움을 기록하고, 학교 일정과 완료 기준에 맞춰 공부 시간을 조정합니다.',1,'초중고','국어·영어·수학',
 '국어 한 시간, 수학 두 시간처럼 정해진 비율을 모든 학생에게 적용할 필요는 없습니다. 같은 과목에서도 읽기와 문제 풀이에 필요한 시간이 다릅니다. 먼저 과제를 해 본 기록으로 다음 배분을 정해 보세요.',[
 ('공부 시간보다 과제의 목적 정하기','시험 준비, 개념 복습, 제출 과제 중 무엇을 해야 하는지 확인합니다. “영어 공부”보다 “학교 지문 두 문장의 구조 확인”처럼 완료 기준을 적으세요. 과제가 달라지면 필요한 시간도 달라지므로 과목 이름만으로 시간표를 고정하지 않습니다.'),
 ('실제 시작과 끝을 기록하기','예상 시간 옆에 실제 걸린 시간을 적습니다. 쉬는 시간과 자료 찾는 시간을 구분하면 무엇 때문에 늘어났는지 볼 수 있습니다. 기록은 시간을 평가하기 위한 점수가 아니라 다음 과제를 조정하기 위한 자료입니다. 처음부터 복잡한 측정 도구를 준비할 필요는 없습니다.'),
 ('시간이 길어진 이유를 분류하기','개념이 낯선지, 문제 문장이 긴지, 계산에서 반복해 멈추는지 살펴봅니다. 같은 과목의 모든 과제를 늘리기보다 막힌 단계에 질문이나 쉬운 예제를 배치할 수 있습니다. 집중이 끊긴 경우에는 환경과 과제의 크기도 함께 확인하세요.'),
 ('마감과 학습 필요를 함께 고려하기','곧 제출할 과제만 반복하면 기본 개념 복습이 계속 밀릴 수 있습니다. 제출 기한이 있는 과제와 다음 학습에 필요한 보완을 나누어 배치하세요. 모든 과목에 매일 같은 시간을 주는 대신 일주일 안에 필요한 과제가 빠지지 않는지 확인합니다.'),
 ('휴식과 이동이 빠지지 않았는지 보기','과목별 시간 합계가 실제 공부 가능한 시간을 넘으면 계획을 고칩니다. 식사나 수면을 줄여 표를 맞추지 마세요. 긴 과제를 두 번으로 나누거나 추가 문제를 뒤로 옮기는 식으로 선택합니다. 시간표에는 과제 사이의 준비와 쉬는 칸도 필요합니다.'),
 ('다음 주에는 한 가지 배분만 바꾸기','매일 전체 시간표를 새로 만들기보다 반복해서 밀리는 과목의 과제 하나를 조정합니다. 예를 들어 설명이 필요한 수학 개념은 질문할 시간에, 혼자 가능한 영어 어휘 확인은 짧은 칸에 둘 수 있습니다. 변경 후 실제 완료 결과를 다시 봅니다.')],
 ('시간 배분 기록 양식',['과목과 오늘 완료할 과제','예상 시간 / 실제 시간 / 중단 이유','혼자 한 부분 / 질문이 필요한 부분','다음 배분에서 줄이거나 옮길 항목']),
 [('수학은 다른 과목보다 오래 해야 하나요?','현재 과제와 학생의 이해 상태에 따라 달라집니다. 모든 학생에게 같은 시간을 권하기보다 실제 소요 시간과 필요한 보완을 보고 배정하세요.'),('시간은 채웠는데 진도가 안 나갔어요.','자료 찾기·개념 이해·풀이 중 어디에서 시간이 걸렸는지 확인하세요. 과제를 작게 나누거나 질문을 준비한 뒤 다음 시간표를 조정합니다.')])

add(17,'수업질문재풀이기록','학원 수업을 활용하는 공부법, 질문과 재풀이 기록하기',
 '학원 수업 전 질문을 준비하고, 받은 힌트와 혼자 재풀이한 결과를 구분해 다음 수업에 연결합니다.',4,'초중고','영어·수학',
 '수업을 듣고 문제를 많이 풀었더라도 어떤 도움을 받았는지 기록이 없으면 다음 과제를 고르기 어렵습니다. 질문 준비와 힌트 기록, 독립 재풀이를 나누어 수업에서 확인할 일을 정해 보세요.',[
 ('수업 전에 막힌 문제 하나 고르기','모르는 문제를 모두 한꺼번에 묻기보다 대표 문제와 막힌 지점을 준비합니다. 조건을 읽었는지, 식을 세웠는지, 개념 이름을 아는지 표시하세요. 무엇부터 할지 전혀 모르겠다면 낯선 단어나 처음 시도한 생각도 질문 자료가 됩니다.'),
 ('답보다 필요한 힌트를 요청하기','정답을 바로 확인하는 대신 어떤 조건을 다시 읽어야 하는지, 연결할 개념이 무엇인지 물어볼 수 있습니다. 학생이 시도한 풀이를 먼저 보여 주면 설명의 범위를 정하기 쉽습니다. 모든 수업에서 같은 질문 방식을 제공하는지는 실제 지점 운영을 확인하세요.'),
 ('받은 도움의 종류를 남기기','공식 안내, 조건 해석, 계산 수정, 문장 구조 설명처럼 도움을 구분합니다. 힌트를 받은 뒤 해결한 문제를 처음부터 혼자 푼 것과 같은 표시로 두지 마세요. 차이를 알면 다음 재확인에서 어떤 부분을 스스로 해볼지 선택할 수 있습니다.'),
 ('재풀이 전에 해설을 가리기','교재를 펼쳤을 때 이전 풀이가 보이면 답을 떠올리기 쉽습니다. 풀이를 가린 뒤 빈 종이에 필요한 조건과 과정을 적어 봅니다. 정답만 기억난다면 설명의 이유를 말하거나 표현이 달라진 문제에서 적용을 확인하세요. 막힌 줄은 다시 질문할 자료로 남깁니다.'),
 ('결과를 다음 수업에 가져가기','재풀이 날짜와 혼자 가능한 단계, 다시 받은 도움을 기록합니다. 같은 오류가 반복되면 추가 문제 수만 늘리기보다 관련 기초를 살펴볼 수 있습니다. 선생님에게 “이 부분은 혼자 했고 여기서 다시 멈췄다”라고 보여 주며 다음 과제를 조정하세요.'),
 ('변화는 과정 자료로 확인하기','특정 학생의 성적 사례를 다른 학생의 결과로 약속할 수는 없습니다. 질문이 구체적으로 바뀌었는지, 도움받은 부분을 혼자 적용했는지 같은 기록으로 과정을 확인하세요. 시험 점수는 여러 조건의 영향을 받으므로 수업 기록과 함께 구분해 해석합니다.')],
 ('문제 한 개의 기록 예시',['첫 시도: 조건은 표시했지만 식을 못 세움','받은 힌트: 비교 기준을 같은 단위로 바꾸기','재풀이: 해설 없이 식을 세웠고 계산에서 멈춤','다음 질문: 계산 중 단위가 바뀌는 줄 확인']),
 [('오답 노트를 꼭 따로 만들어야 하나요?','교재 여백이나 간단한 기록표로 시작해도 됩니다. 문제를 옮겨 적는 양보다 받은 도움과 재풀이 결과가 구분되는지가 중요합니다.'),('틀린 문제를 다시 맞히면 끝인가요?','정답을 기억한 것인지 이유를 이해한 것인지 설명해 보세요. 필요하면 조건이나 표현이 달라진 기본 문제로 적용을 확인합니다.')])

add(18,'아침공부습관시작','아침 공부 습관, 수면을 줄이지 않고 시작하는 방법',
 '학생의 아침 생활과 수면을 먼저 확인하고, 짧은 과제·준비·실행 기록으로 아침 공부의 적합성을 살핍니다.',3,'초중고','',
 '아침 공부가 모든 학생에게 가장 좋은 방법인 것은 아닙니다. 일찍 일어나기 전에 충분한 수면과 등교 준비가 가능한지 확인하세요. 무리 없이 시작할 수 있을 때 익숙한 작은 과제로 시험해 보는 방식입니다.',[
 ('아침에 공부할 여유가 있는지 확인하기','현재 기상·취침 시간과 아침 식사, 준비 시간을 적습니다. 공부를 넣기 위해 잠을 줄여야 한다면 다른 시간대를 먼저 검토하세요. 아침에 계속 졸리는 상태를 의지 문제로 단정하지 말고 수면과 생활 일정을 함께 살펴봅니다.'),
 ('밤에 자료를 미리 준비하기','아침마다 교재를 찾거나 무엇을 할지 고민하지 않도록 전날 작은 과제를 고릅니다. 책상에 필요한 자료만 두고 시작할 쪽을 표시하세요. 준비 자체가 복잡해지지 않도록 단어 확인 카드나 이미 배운 예제처럼 익숙한 자료부터 선택할 수 있습니다.'),
 ('낯선 진도보다 확인 과제로 시작하기','처음에는 새 단원을 길게 배우기보다 짧은 어휘 확인, 전날의 개념 설명, 읽을 문단 하나를 고릅니다. 완료 기준을 한눈에 볼 수 있어야 합니다. 과제가 너무 쉽게 느껴지거나 시작부터 막히면 다음 날 범위와 도움 수준을 조절하세요.'),
 ('실행 여부와 등교 준비를 함께 기록하기','공부를 했는지만 표시하지 말고 준비가 바빠졌는지, 아침 식사를 미뤘는지도 봅니다. 학생이 스스로 자료를 펴는지와 과제 완료 결과를 나누어 기록하세요. 생활이 계속 촉박해지면 아침 과제를 줄이거나 다른 시간으로 옮길 수 있습니다.'),
 ('습관 형성 기간을 약속하지 않기','누구나 3주면 습관이 완성된다고 말하기 어렵습니다. 처음에는 준비, 시작, 종료 약속을 시험해 보고 학생의 반응에 맞춰 조정하세요. 여러 날 실패했다는 이유로 사람을 평가하지 말고 과제 크기와 시간대가 맞는지 확인합니다.'),
 ('잘 맞지 않으면 다른 시간으로 옮기기','아침에 혼자 확인하기 어려운 내용은 방과 후나 도움받을 수 있는 시간에 둘 수 있습니다. 중요한 것은 특정 시간대의 이름보다 지속 가능한 공부 흐름입니다. 가족 일정과 학생의 컨디션을 함께 고려해 더 편안하게 실행할 수 있는 칸을 찾으세요.')],
 ('아침 공부를 시험해 볼 조건',['수면과 아침 식사 시간을 확보할 수 있는가?','전날 자료와 첫 과제를 준비할 수 있는가?','등교 준비를 방해하지 않는 작은 범위인가?','맞지 않을 때 옮길 시간대가 있는가?']),
 [('무조건 일찍 깨워야 하나요?','수면을 줄이면서 아침 과제를 만들 필요는 없습니다. 현재 생활에서 여유가 있는지 먼저 확인하고 부족하다면 다른 시간대를 선택하세요.'),('몇 주면 습관이 완성되나요?','일정 기간을 모든 학생에게 보장할 수 없습니다. 실행 기록과 생활의 부담을 보면서 과제와 시간을 점진적으로 조정합니다.')])

add(19,'중고등공부목표선택','중고등학생 공부 동기, 학생이 선택할 목표 함께 정하기',
 '중고등학생이 공부의 이유를 말하고 목표와 과제를 선택하도록 돕는 대화·완료 기준·지원 방법을 정리합니다.',3,'중고','',
 '“왜 공부해야 하니?”라는 질문에 학생이 쉽게 답하지 못할 수도 있습니다. 먼 진로나 점수 목표부터 강요하기보다 지금 어렵거나 바꾸고 싶은 과제를 듣고, 학생이 선택할 수 있는 목표로 연결해 보세요.',[
 ('학생이 중요하게 느끼는 이유 듣기','부모가 생각하는 이유와 학생의 이유가 같지 않을 수 있습니다. 수업을 더 이해하고 싶은지, 밀린 과제가 부담인지, 관심 있는 분야를 읽고 싶은지 물어보세요. 바로 설득하기보다 학생이 말한 이유를 오늘의 과제와 연결할 수 있는지 살핍니다.'),
 ('결과 목표와 행동 목표를 나누기','점수나 등수는 여러 조건의 영향을 받습니다. “시험에서 잘하기” 옆에 “학교 자료의 어려운 두 문장을 질문하기”처럼 실행할 행동을 적으세요. 목표가 크게 느껴지면 이번 주에 끝낼 범위를 줄이고 완료를 확인할 자료를 정합니다.'),
 ('학생이 고를 수 있는 범위 주기','해야 할 과제가 정해져 있어도 순서나 시작 자료를 선택할 수 있습니다. 두 과제 중 먼저 할 것을 고르게 하거나 질문할 방법을 논의해 보세요. 모든 선택을 대신하거나 반대로 전부 혼자 맡기기보다 현재 가능한 역할을 함께 정합니다.'),
 ('중학생은 학교 과제를 구체화하기','평가 범위와 제출 기준을 보고 지금 준비할 단계를 나눕니다. 과목이 많아 혼란스럽다면 목록을 만들고 급한 항목과 기초 보완을 구분하세요. 부모는 안내를 확인하는 일을 도울 수 있지만 학생의 풀이와 결과를 대신하지 않도록 역할을 정합니다.'),
 ('고등학생은 우선순위 근거를 남기기','학교 수업과 평가 준비가 겹치면 무엇을 먼저 할지 선택한 이유를 적습니다. 어려운 과목이라는 느낌보다 단원별 독립 적용과 질문 기록을 볼 수 있습니다. 진로·평가 제도와 관련된 결정은 학교의 현재 안내와 상담을 확인하며 임의로 단정하지 않습니다.'),
 ('목표가 바뀌어도 대화를 이어가기','실행하지 못한 목표에는 시간이 부족했는지, 과제가 어려웠는지, 의미를 느끼지 못했는지 이유가 있을 수 있습니다. 약속을 어겼다는 평가만 남기기보다 다음 목표의 범위를 조절하세요. 학생이 맡을 행동과 부모·선생님이 도울 일을 따로 적습니다.')],
 ('목표를 정할 때 쓸 대화',['지금 공부에서 바꾸고 싶은 것은 무엇이니?','이번 주에 혼자 해보고 싶은 과제는 무엇이니?','둘 중 어느 과제부터 시작하면 좋을까?','끝낸 것을 무엇으로 확인하고 어떤 도움을 받을까?']),
 [('진로가 없으면 공부 목표를 못 정하나요?','지금 수업을 이해하거나 과제를 끝내고 싶은 이유에서도 시작할 수 있습니다. 먼 진로가 확정되지 않았더라도 작은 행동 목표를 정해 보세요.'),('학생이 고른 목표가 너무 작아요.','실제로 끝낼 수 있는지 먼저 확인하세요. 완료 기록과 어려움을 본 뒤 다음 범위를 늘리거나 필요한 과제로 연결할 수 있습니다.')])

add(20,'공부시작미루기','공부 시작이 미뤄질 때, 환경과 목표를 작게 바꾸는 방법',
 '공부 시작을 미루는 상황을 자료 준비·과제 크기·알림·도움 요청으로 나누고, 첫 행동을 정하는 방법을 안내합니다.',3,'초중고','',
 '공부하려고 앉았는데 시작이 안 된다면 의욕이 생길 때까지 기다리기보다 멈추는 조건을 찾아보세요. 책을 펴는 준비와 첫 과제, 막혔을 때의 도움 요청을 나누면 바꿀 부분이 보입니다.',[
 ('미루는 장면을 구체적으로 적기','몇 시에 어떤 과제를 앞두고 멈췄는지 기록합니다. 자료가 없었는지, 할 일이 너무 넓었는지, 어려울 것 같아 걱정됐는지 나누세요. “항상 게으르다”는 평가로 묶으면 다음에 바꿀 행동이 드러나지 않습니다.'),
 ('시작 전에 결정할 일을 줄이기','교재를 고르고 쪽수를 찾고 필기구를 준비하는 일이 매번 반복되는지 확인합니다. 이전 공부가 끝날 때 다음 첫 과제를 적어 둘 수 있습니다. 시작 순간에는 준비된 자료를 펴고 무엇을 확인할지만 알 수 있도록 책상과 목록을 정리하세요.'),
 ('큰 목표를 첫 행동으로 바꾸기','“영어 한 단원 끝내기”를 “첫 문장의 주어와 동사 표시하기”로 바꿔 볼 수 있습니다. 첫 행동이 끝난 뒤 다음 범위를 선택하세요. 과제를 작게 나눈다고 학습 목표를 없애는 것은 아닙니다. 어디까지 완료해야 하는지도 별도 목록으로 남깁니다.'),
 ('알림과 다른 활동의 시간을 구분하기','공부 중 휴대전화나 영상으로 자주 흐름이 끊기면 학생이 동의할 수 있는 사용 약속을 정합니다. 자료 검색에 기기가 필요한 경우도 있으므로 무조건 없애기보다 목적과 시간을 나누세요. 알림을 줄인 뒤 실제 시작과 중단이 어떻게 달라지는지 확인합니다.'),
 ('막혔을 때의 다음 행동 준비하기','모르는 문제가 나오면 책을 덮는 대신 낯선 용어, 시도한 풀이, 멈춘 줄을 적습니다. 질문할 시간과 사람을 정해 두면 어려운 부분을 숨기지 않고 다룰 수 있습니다. 당장 도움받기 어렵다면 표시를 남기고 혼자 가능한 다음 과제로 옮길 기준을 정하세요.'),
 ('보상보다 실행 조건을 먼저 살피기','과제를 끝내면 쉬는 활동을 할 수 있지만 보상만 계속 늘려서 시작을 해결하려 하지 않습니다. 과제 크기와 도움 수준, 시간대가 맞는지 먼저 확인하세요. 며칠의 실행 기록으로 바꿀 조건 하나를 고르고 다음에 다시 점검합니다.')],
 ('오늘 바꿔볼 첫 행동',['시작할 교재와 쪽수를 미리 적기','혼자 할 수 있는 첫 과제 하나 고르기','알림과 쉬는 활동의 시간 약속 정하기','막힌 줄을 표시하고 질문할 방법 남기기']),
 [('시작만 하고 금방 멈춰요.','첫 과제 다음 단계가 너무 크거나 어려운지 확인하세요. 완료 기준과 도움받을 부분을 나누고 실제로 멈춘 지점을 기록합니다.'),('휴대전화를 빼앗으면 해결되나요?','알림은 한 조건일 수 있지만 과제 난도와 준비 문제도 함께 살펴야 합니다. 학생과 사용 목적·시간을 합의하고 결과를 확인하세요.')])

add(21,'여름방학하루루틴','여름방학 공부 습관, 하루 루틴과 휴식 함께 만들기',
 '여름방학의 여행·가족 일정과 생활 리듬을 고려해 시작 과제, 쉬는 시간, 복귀 루틴과 주간 점검을 정리합니다.',3,'초중고','',
 '여름방학에는 여행과 가족 일정, 평소와 다른 활동이 생길 수 있습니다. 매일 같은 진도를 강요하기보다 평소 날과 일정이 있는 날의 공부 흐름을 나누어 보세요. 개학 후에도 이어갈 작은 습관을 찾는 것이 목표입니다.',[
 ('방학 중에도 남길 생활 기준 정하기','수면과 식사, 공부를 시작할 시간대를 가족 일정 안에서 정합니다. 늦게 일어난 날의 공부를 밤으로 전부 미루는 방식은 부담이 될 수 있습니다. 여행이나 외출이 있는 날은 고정된 시간표 대신 가능한 과제를 따로 선택하세요.'),
 ('평소 날과 외출하는 날의 과제 나누기','집에서 충분히 공부할 수 있는 날에는 개념 확인과 적용 과제를 연결합니다. 이동이나 가족 일정이 많은 날에는 짧은 읽기나 이전 학습 확인처럼 준비가 간단한 과제를 정할 수 있습니다. 외출 시간을 모두 공부로 채우기보다 쉬는 목적도 함께 존중하세요.'),
 ('공부 공간을 시작하기 쉬운 상태로 두기','교재와 자료가 흩어져 있으면 시작 시간이 길어질 수 있습니다. 자주 쓸 자료를 한곳에 모으고 오늘의 첫 과제만 펼쳐 두세요. 더운 날에는 편안하게 공부할 수 있는 장소와 쉬는 시간을 살피되 무리한 활동으로 일정을 채우지 않습니다.'),
 ('휴식 뒤 돌아올 행동을 적기','쉬기 전에 다음에 풀 문제나 읽을 문단을 표시합니다. 휴식이 끝나면 자료를 찾는 것부터 다시 시작하지 않도록 준비하세요. 게임이나 영상 사용은 가능한 시간과 종료 약속을 함께 정하고 실제로 지키기 어려운 조건은 조정합니다.'),
 ('여행 이후의 복귀 과제는 작게 시작하기','빠진 진도를 한 번에 몰아 넣으면 일상으로 돌아오기가 더 어려울 수 있습니다. 처음에는 이전에 배운 예제와 짧은 확인 과제로 시작하세요. 남은 방학 일정과 학교 과제를 보고 복습·예습의 우선순위를 다시 정합니다.'),
 ('일주일에 한 번 유지할 습관 고르기','가장 오래 공부한 날보다 시작과 종료 약속이 잘 맞았던 날을 살펴봅니다. 학생이 혼자 자료를 준비했는지, 질문을 남겼는지도 볼 수 있습니다. 개학 후에도 유지할 행동 한 가지를 골라 등교 일정 안에 넣을 수 있는지 확인하세요.')],
 ('방학 루틴의 세 가지 버전',['평소 날: 개념 확인 → 혼자 적용 → 결과 기록','외출하는 날: 준비가 쉬운 작은 확인 과제','복귀하는 날: 익숙한 예제부터 다시 시작','공통 기준: 생활과 휴식을 포함해 실행 결과 보기']),
 [('여행 중에도 매일 공부해야 하나요?','가족 일정과 쉬는 목적을 함께 고려하세요. 가능한 과제를 작게 정하거나 복귀 이후에 배치할 수 있으며 무리하게 모든 진도를 유지할 필요는 없습니다.'),('방학에 만든 습관을 개학 후 어떻게 이어가나요?','학교 일정에 들어갈 작은 행동을 선택하세요. 자료 준비나 짧은 재확인처럼 실제로 유지할 수 있는 범위부터 조정합니다.')])

add(22,'수업후복습순서','학원 수업 후 복습, 설명을 들은 뒤 혼자 확인하는 순서',
 '수업 후 불확실했던 내용을 골라 자료 없이 설명·적용하고, 재확인 결과와 질문을 다음 수업에 연결합니다.',2,'초중고','영어·수학',
 '복습을 얼마만큼 하면 성적이 오른다는 비율을 정하기보다 오늘 설명을 들은 내용 중 혼자 확인할 부분을 골라 보세요. 읽어 본 풀이와 실제로 해 본 결과를 구분하는 것이 이 글의 핵심입니다.',[
 ('수업이 끝날 때 확인할 내용 고르기','오늘 배운 모든 내용을 같은 깊이로 다시 볼 필요는 없습니다. 질문했던 개념, 도움받은 풀이, 헷갈린 문장 중 대표 항목을 고릅니다. 교재 쪽수와 확인할 질문을 적어 두면 집에서 복습 범위를 다시 찾는 시간을 줄일 수 있습니다.'),
 ('먼저 자료 없이 기억을 꺼내 보기','설명이나 답을 보기 전에 개념을 말하거나 문제를 시도합니다. 미국 교육과학연구소의 학습 안내는 기억을 꺼내 보는 연습과 학습을 나누어 배치하는 방법을 다룹니다. 이를 적용할 때는 틀린 부분을 확인하고 다시 학습하는 과정까지 포함하세요.'),
 ('기억과 실제 자료의 차이를 확인하기','생각한 설명과 교과서의 조건이 다른지, 풀이에서 빠진 단계가 있는지 비교합니다. 정답을 틀렸다는 표시만 남기지 말고 무엇을 수정했는지 적으세요. 답을 읽고 곧바로 이해됐다고 느낀 경우도 다음 독립 확인에서 다시 살펴볼 부분입니다.'),
 ('기본 적용 과제로 이어가기','수학은 개념을 선택한 이유를 설명하며 기본 문제를 풀 수 있습니다. 영어는 해당 문장을 해석하고 구조나 표현을 다른 문장에서 확인할 수 있습니다. 풀이 전체를 베껴 쓰기보다 지금 불확실했던 부분이 적용되는지 확인하세요.'),
 ('다른 날의 재확인을 계획하기','한 번 맞혔다고 항상 기억된다고 단정하지 않습니다. 다음 공부 일정에서 다시 확인할 과제를 적고, 이미 가능한 부분과 다시 어려운 부분을 구분하세요. 모든 학생과 내용에 맞는 고정 간격을 정하기보다 잊은 정도와 과제 일정을 보고 조절합니다.'),
 ('남은 질문을 다음 지도에 연결하기','혼자 가능한 부분, 다시 도움받은 부분, 아직 모르는 문장을 기록합니다. 수업에 가져갈 질문은 시도한 과정과 함께 적어 보세요. 복습을 했는지 체크하는 데서 끝내지 않고 다음 수업의 설명과 과제 선택에 결과를 활용합니다.')],
 ('수업 후 복습의 확인 순서',['불확실했던 개념이나 문제 하나 고르기','자료를 덮고 설명하거나 풀어 보기','교재와 비교해 빠진 조건·단계 수정하기','다른 날 재확인하고 남은 질문 가져가기']),
 [('복습은 배운 내용의 절반만 하면 되나요?','모든 학생에게 같은 비율을 정할 근거는 없습니다. 현재 불확실한 부분과 학교 과제를 고려해 확인할 범위를 선택하세요.'),('해설을 읽었으면 복습한 건가요?','읽기는 확인 과정의 일부입니다. 해설을 보지 않고 설명하거나 적용한 결과를 함께 살펴야 다음 과제를 고를 수 있습니다.')],['learning'])

add(23,'학년별자기주도역할','학년별 자기주도학습, 초·중·고에서 맡길 역할 나누기',
 '초·중·고 학생의 현재 수준에 맞춰 자료 준비·과제 선택·결과 점검 역할을 나누고, 도움을 줄이는 순서를 정리합니다.',3,'초중고','',
 '자기주도학습은 모든 과제를 혼자 버티는 뜻이 아닙니다. 필요한 도움을 요청하면서 준비·실행·점검의 역할을 조금씩 맡는 과정으로 살펴보세요. 학년은 참고 기준이며 실제 가능한 역할은 학생마다 다릅니다.',[
 ('현재 혼자 할 수 있는 일을 먼저 보기','교재 준비, 첫 과제 선택, 마무리 기록 중 가능한 일을 확인합니다. 학년이 올라갔다고 모든 계획을 바로 맡기거나 어린 학생에게 아무 역할도 주지 않을 필요는 없습니다. 부모와 선생님이 도울 부분을 구분하고 학생의 시도 결과를 봅니다.'),
 ('초등: 시작과 마무리 약속 정하기','자료를 준비하고 정해 둔 작은 과제를 시작하는 역할부터 맡길 수 있습니다. 끝나면 혼자 한 부분과 질문이 필요한 부분을 표시합니다. 분량과 시간은 생활에 맞게 작게 시작하고 부모는 완료 기준을 이해했는지 확인하는 역할을 도울 수 있습니다.'),
 ('중등: 여러 과제의 순서 선택하기','학교 과목과 제출 과제가 늘어나면 목록을 만들고 기한을 확인하는 일이 필요합니다. 오늘 해야 할 일과 기초 보완을 나눠 우선순위를 정해 보세요. 학생이 순서를 선택한 이유를 설명하고 미완료 원인을 기록하도록 도울 수 있습니다.'),
 ('고등: 계획을 근거로 조정하기','계획과 실제 소요 시간, 독립 적용 결과를 함께 보고 다음 범위를 정합니다. 진도를 많이 넘겼는지보다 어떤 개념에서 다시 질문이 필요한지 확인하세요. 학교 평가와 진로 관련 결정은 현재 학교 자료와 상담에 연결하며 혼자 추측해서 판단하지 않습니다.'),
 ('도움은 단계별로 바꾸기','처음에는 과제 선택을 함께 하고 익숙해지면 학생이 먼저 제안하도록 할 수 있습니다. 어려워졌을 때 도움을 다시 늘리는 것도 가능합니다. 역할을 맡겼다는 이유로 결과를 방치하지 말고 합의한 점검 시점에 기록과 학생의 의견을 함께 확인하세요.'),
 ('기록을 감시가 아닌 조정에 사용하기','미완료 표시가 쌓일 때 꾸짖는 자료로만 쓰지 않습니다. 과제 크기와 생활 일정, 도움받을 방법이 적절했는지 살펴보세요. 학생이 어떤 기록을 누구와 공유할지 알 수 있도록 정하고 실제로 도움이 되는 항목만 남깁니다.')],
 ('현재 맡길 수 있는 역할 선택',['준비: 필요한 자료와 첫 과제 챙기기','실행: 시도한 풀이와 막힌 지점 표시하기','점검: 혼자 한 결과와 미완료 이유 기록하기','조정: 다음 과제와 필요한 도움 제안하기']),
 [('자기주도학습은 부모가 관여하지 않아야 하나요?','필요한 안내와 생활 지원은 제공할 수 있습니다. 학생이 직접 맡을 행동을 구분하고 점검 방법을 합의하면서 도움의 범위를 조절하세요.'),('학년보다 계획 능력이 부족한 것 같아요.','학년만으로 능력을 단정하지 마세요. 준비·선택·기록 중 현재 가능한 역할 하나부터 맡기고 실제 어려움에 맞춰 지원합니다.')])

add(24,'중학생공부순서','중학생 공부 순서, 개념 확인에서 적용·복습까지',
 '중학생의 공부를 범위 확인·개념 설명·기본 적용·오류 수정·재확인으로 나누고, 막힌 단계에 맞춰 순서를 조정합니다.',2,'중','',
 '어떤 과목부터 시작해야 할지보다 한 과제를 어떤 순서로 확인할지 정해 보세요. 개념을 읽고 문제를 푼 뒤 결과를 다음 공부에 연결하는 흐름입니다. 이미 아는 정도에 따라 시작 단계는 달라질 수 있습니다.',[
 ('오늘 확인할 범위와 질문 읽기','학교 수업 범위와 과제의 요구를 먼저 확인합니다. 무엇을 설명하거나 해결해야 하는지 한 문장으로 적으세요. 교재 전체를 무조건 처음부터 읽기보다 오늘 과제와 연결되는 자료 위치를 찾으면 필요한 공부가 보입니다.'),
 ('개념을 자신의 말로 설명하기','용어를 읽은 뒤 뜻과 예를 말해 봅니다. 과학의 상태 변화라면 현상의 이름뿐 아니라 어떤 조건에서 바뀌는지 확인할 수 있습니다. 설명이 막힐 때는 예시와 그림을 보고 낯선 말을 먼저 정리하세요. 용어 암기와 의미 이해를 나누어 살핍니다.'),
 ('예제에서 과정의 이유 확인하기','풀이를 따라 썼다고 이해가 끝난 것은 아닙니다. 조건을 어떻게 읽고 어떤 개념을 선택했는지 확인하세요. 이미 기본 개념을 설명할 수 있다면 독립 적용부터 시도할 수 있습니다. 모든 학생이 매번 같은 단계에서 시작할 필요는 없습니다.'),
 ('해설 없이 기본 과제 해보기','국어는 근거 문장을 찾고, 영어는 문장의 관계를 읽고, 수학은 기본 문제를 혼자 풀어 봅니다. 개념을 떠올릴 수 있는지와 실제 적용이 되는지를 구분하세요. 막힌 경우에는 문제 번호와 멈춘 줄을 표시해 도움을 요청할 자료로 만듭니다.'),
 ('오류의 종류에 맞게 되돌아가기','용어가 낯설면 개념 확인으로, 조건을 놓쳤다면 읽기로, 계산이 틀렸다면 그 줄의 계산 점검으로 돌아갑니다. 틀린 문제를 모두 같은 방식으로 여러 번 푸는 대신 필요한 단계만 다시 확인하세요. 수정한 이유를 짧게 적어 두면 재확인 때 비교하기 쉽습니다.'),
 ('다음 공부에서 확인할 내용을 남기기','오늘 맞힌 문제 중 도움받은 부분과 혼자 한 부분을 구분합니다. 다음 날이나 다음 관련 수업에서 다시 설명할 과제를 남길 수 있습니다. 공부가 끝날 때 새로운 진도만 정하지 말고 남은 질문과 재확인 항목도 같이 준비하세요.')],
 ('막힌 단계에 따른 다음 행동',['용어가 낯설다 → 쉬운 예로 뜻 확인','설명은 가능하지만 못 푼다 → 기본 적용 시도','조건을 놓쳤다 → 문제 요구와 조건 표시','해설은 알겠지만 혼자 못 한다 → 힌트 기록 후 재확인']),
 [('항상 개념부터 읽어야 하나요?','이미 설명할 수 있는 내용이면 적용 과제부터 확인할 수 있습니다. 결과를 보고 필요한 개념으로 돌아가며 순서를 조정하세요.'),('틀린 문제는 전부 다시 풀어야 하나요?','오류의 원인과 우선 범위를 먼저 확인하세요. 필요한 대표 문제와 기초를 골라 수정한 뒤 혼자 적용되는지 살펴봅니다.')])

add(25,'과목별공부과제구분','과목별 학습 전략, 읽기·풀이·기억 과제 구분하기',
 '과목 공부를 읽기·관계 정리·문제 풀이·기억 확인으로 구분하고, 과제 목적에 맞는 방법과 완료 기준을 정리합니다.',2,'초중고','국어·영어·수학',
 '교재를 오래 읽거나 문제를 많이 푸는 한 가지 방식만으로 모든 과제를 다루기는 어렵습니다. 먼저 지금 해야 할 일이 읽기인지, 관계를 설명하는 일인지, 적용이나 기억 확인인지 구분해 보세요.',[
 ('읽기 과제는 의미와 근거 확인하기','국어 지문이나 영어 문장을 읽을 때 이해하지 못한 표현과 문장 관계를 표시합니다. 밑줄의 양보다 왜 그 문장이 중요하다고 생각했는지 설명해 보세요. 답을 고르는 문제라면 본문 근거와 선택지의 표현이 어떻게 연결되는지도 확인합니다.'),
 ('관계 정리는 기준을 먼저 정하기','사회의 사건이나 과학의 개념을 표로 만들 때는 비교 기준을 정합니다. 원인·과정·결과, 공통점·차이점처럼 관계가 보이는 항목을 고르세요. 꾸미는 작업에 시간을 쓰기보다 표를 보지 않고 관계를 설명한 결과로 빠진 부분을 확인합니다.'),
 ('풀이 과제는 선택한 이유 남기기','수학 문제에서는 어떤 조건 때문에 해당 식이나 개념을 골랐는지 적습니다. 과학의 계산 문제도 단위와 관계를 먼저 확인할 수 있습니다. 정답 여부만 모으면 반복되는 오류를 보기 어렵습니다. 읽기·개념 선택·계산 중 다시 볼 단계를 구분하세요.'),
 ('기억 과제는 답을 보기 전에 확인하기','단어와 용어를 확인할 때 먼저 뜻이나 설명을 떠올리고 실제 자료와 비교합니다. 떠올리지 못한 항목은 다시 읽고 다음 확인 목록에 남기세요. 모든 내용을 같은 횟수로 외우기보다 아직 불확실한 부분과 이미 가능한 부분을 나눕니다.'),
 ('학교 평가 방식과 연결하기','같은 과목이라도 서술형, 자료 해석, 구술·발표 등 과제의 요구가 다를 수 있습니다. 현재 학교 안내와 수업 자료를 확인해 실제 필요한 표현과 풀이를 준비하세요. 특정 시험의 방식이나 일정이 모든 학교에 같다고 가정하지 않습니다.'),
 ('완료 기준을 과제 유형에 맞추기','읽기는 의미와 근거 설명, 관계 정리는 기준에 따른 비교, 풀이는 독립 적용, 기억 확인은 자료 없이 설명한 결과로 살펴볼 수 있습니다. 하나의 단원에도 여러 유형이 섞일 수 있습니다. 부족한 유형을 다음 과제로 골라 공부 방식의 빈칸을 줄이세요.')],
 ('과제 유형과 확인 결과',['읽기: 문장의 뜻과 답의 근거 설명','관계: 비교 기준으로 원인·차이 정리','풀이: 조건을 읽고 개념 선택·적용','기억: 자료 없이 뜻·과정 설명 후 수정']),
 [('암기 과목은 읽기만 반복하면 되나요?','읽은 뒤 자료 없이 설명한 결과를 확인해 보세요. 필요한 관계나 평가 방식에 따라 비교·적용 과제도 함께 정할 수 있습니다.'),('한 과목에는 한 방법만 쓰면 되나요?','한 단원 안에도 읽기·기억·적용 과제가 섞일 수 있습니다. 현재 부족한 과제 유형을 보고 방법과 완료 기준을 선택하세요.')])

add(26,'월간주간일간계획표','2학기 공부 계획표, 월간·주간·일간 기록 연결하기',
 '2학기 학교 일정과 과제를 월간·주간·일간 계획에 나누고, 실제 공부 결과로 다음 계획을 조정하는 방법을 정리합니다.',1,'초중고','',
 '월간표에는 일정이, 하루표에는 해야 할 일이 들어갑니다. 두 표가 연결되지 않으면 마감일은 아는데 언제 시작할지 모를 수 있습니다. 학교 안내에서 확인한 일정을 주간 과제와 오늘의 완료 기준으로 옮겨 보세요.',[
 ('월간표에는 날짜가 있는 일 넣기','시험, 제출 과제, 학교 행사와 가족의 고정 일정을 적습니다. 아직 확정되지 않은 날짜는 확인할 시점을 남기세요. 월간표를 세세한 공부 시간으로 모두 채우기보다 한 달의 일정이 겹치는 구간을 볼 수 있도록 정리합니다.'),
 ('주간표에는 필요한 준비 단계 나누기','제출 과제 하나도 자료 확인, 초안, 수정과 최종 제출로 나눌 수 있습니다. 시험 준비에는 개념 확인과 독립 적용, 질문을 배치하세요. 마감 바로 앞에 전체 과제를 넣지 않도록 앞선 주에 시작할 부분을 고릅니다.'),
 ('하루표에는 실행할 자료와 범위 적기','“영어”만 쓰지 말고 교재 쪽수와 확인할 문장을 적습니다. 완료 기준이 있어야 실제 결과와 비교할 수 있습니다. 하루의 고정 일정 뒤 남는 시간을 확인하고 우선 과제를 고르세요. 계획을 적는 시간이 공부 시간을 지나치게 차지하지 않도록 항목을 줄일 수 있습니다.'),
 ('실제 결과를 계획 옆에 기록하기','예상한 분량과 실제 한 부분, 걸린 시간과 도움받은 내용을 남깁니다. 체크하지 못한 날은 실패 표시만 남기지 말고 이유를 적으세요. 일정 변화, 과제 난도, 자료 준비 문제를 나누면 다음 계획에서 고칠 부분이 보입니다.'),
 ('주간 점검에서 옮길 것과 줄일 것 고르기','미완료 과제를 다음 날에 전부 복사하면 하루 부담이 커질 수 있습니다. 기한과 학습 필요를 보고 남길 항목, 도움받을 항목, 범위를 줄일 항목을 고릅니다. 계획에 조정 칸을 남겨 예상 밖 일정에도 수정할 수 있게 합니다.'),
 ('부모와 공유할 항목은 함께 정하기','모든 기록을 매시간 검사하는 방식은 학생에게 부담이 될 수 있습니다. 일정과 완료 결과 중 함께 볼 항목과 시간을 합의하세요. 부모는 기한과 생활의 충돌을 돕고 학생은 실제 막힌 지점과 다음 과제를 제안하는 식으로 역할을 나눌 수 있습니다.')],
 ('세 표를 잇는 예시',['월간: 학교 안내에서 확인한 과제 제출일','주간: 자료 읽기 → 초안 → 수정 날짜','일간: 오늘 읽을 자료와 초안 한 항목','결과: 실제 작성 부분과 내일 보완할 질문']),
 [('계획표를 세 종류 모두 만들어야 하나요?','하나의 표 안에 일정·이번 주 과제·오늘 할 일을 구분해도 됩니다. 형식보다 마감과 실행 과제가 연결되는지가 중요합니다.'),('체크 표시가 적으면 계획을 더 엄격히 해야 하나요?','미완료 이유와 실제 시간을 먼저 확인하세요. 과제 범위나 일정이 맞지 않았다면 계획을 조정하는 것이 필요합니다.')])

add(27,'학습점검피드백행동','학습 상태 점검과 피드백, 조언을 다음 행동으로 옮기기',
 '학습 목표와 독립 수행 결과를 비교하고, 피드백을 구체적인 수정·재확인 과제로 연결하는 방법을 정리합니다.',2,'초중고','',
 '피드백을 들었는데 다음에 무엇을 해야 할지 모르겠다면 조언을 작은 행동으로 옮겨 보세요. 목표, 실제 결과, 수정할 단계와 재확인 날짜를 연결하면 같은 설명을 반복해서 듣는 상황을 점검할 수 있습니다.',[
 ('점검할 목표를 한 가지로 정하기','단원 전체를 평가하려 하기보다 현재 확인할 행동을 고릅니다. “조건을 읽고 식을 세울 수 있다”처럼 결과가 보이는 기준을 씁니다. 목표가 모호하면 잘했는지 못했는지의 인상만 남기기 쉽습니다. 확인할 자료와 문제도 함께 정하세요.'),
 ('혼자 한 결과와 도움받은 결과 나누기','첫 풀이, 힌트를 받은 풀이, 재확인 결과를 구분합니다. 정답이 같아도 도움의 정도는 다를 수 있습니다. 공부한 시간과 문제 수 외에 어떤 단계에서 도움받았는지를 적으면 피드백에서 다룰 범위가 구체적으로 보입니다.'),
 ('조언을 행동 문장으로 바꾸기','“문제를 꼼꼼히 읽자”는 말은 “무엇을 구하는지 한 줄로 쓰고 조건을 표시하자”로 바꿀 수 있습니다. “복습하자”는 “해설을 가리고 첫 두 단계를 다시 설명하자”로 정합니다. 학생이 어떻게 실행할지 자신의 말로 설명하도록 해 보세요.'),
 ('수정하는 이유를 함께 확인하기','왜 그 단계를 다시 봐야 하는지 모르면 기록만 따라 할 수 있습니다. 조건을 놓쳐 식이 달라졌는지, 용어를 오해해 답의 근거가 바뀌었는지 확인하세요. 학생의 기존 시도를 무시하기보다 맞게 한 부분과 수정할 부분을 구분합니다.'),
 ('재확인 과제를 실제 일정에 넣기','피드백을 받은 날에 수정한 결과와 다른 날의 독립 확인을 나눌 수 있습니다. 학교·수업 일정에 맞춰 자료와 범위를 정하세요. 모든 문제를 다시 옮겨 쓰기보다 수정한 단계가 들어 있는 대표 과제를 골라 적용 여부를 확인합니다.'),
 ('다음 피드백에 결과 돌려주기','수정한 행동이 도움이 됐는지와 여전히 막힌 부분을 기록합니다. 같은 문제가 이어지면 과제 수만 늘리지 말고 기초나 설명 방식을 다시 살펴보세요. 피드백은 한 번의 평가로 끝나기보다 다음 과제 선택과 지도 조정의 자료로 활용합니다.')],
 ('피드백을 옮기는 기록 예시',['목표: 문장의 비교 기준을 파악하기','결과: 답을 골랐지만 근거를 찾지 못함','다음 행동: 비교 대상과 근거 문장 표시','재확인: 다른 짧은 지문에서 혼자 적용']),
 [('피드백을 받아도 같은 실수를 해요.','조언이 실제 어떤 행동으로 바뀌었는지 확인하세요. 적용 과제를 해 본 결과와 남은 어려움을 보여 주며 필요한 기초나 설명을 다시 상담합니다.'),('점수 말고 무엇을 기록할까요?','시도한 과정, 도움받은 단계, 수정 이유와 혼자 재확인한 결과를 기록할 수 있습니다. 점수는 이 자료들과 구분해 함께 해석하세요.')])

add(28,'학습코칭도구비교','학습코칭 방법 비교, 질문·자료·플래너 활용 살펴보기',
 '질문 코칭과 플래너·오답·백지노트·AI 자료의 역할을 구분하고, 지점 상담에서 실제 활용을 확인할 질문을 정리합니다.',4,'초중고','',
 '새로운 기법이라는 이름보다 도구를 어떤 과제에 쓰는지 확인해 보세요. 질문, 플래너, 오답 자료와 AI는 역할이 다르며 같은 도구도 지도 방식에 따라 활용이 달라질 수 있습니다.',[
 ('질문 코칭은 사고 과정을 확인하는 데 쓰기','“왜 이 식을 선택했니?”처럼 학생의 판단을 듣는 질문이 있을 수 있습니다. 정답을 말할 때까지 기다리는 것만으로 코칭이라고 판단하지 마세요. 모르는 용어나 시작 단계가 있다면 적절한 설명과 힌트가 어떻게 제공되는지 확인합니다.'),
 ('플래너는 계획과 실행의 차이 보기','일정표를 쓰는 일과 실제 과제를 조정하는 일은 다릅니다. 과제 완료, 소요 시간, 미완료 원인을 누가 어떤 주기로 보는지 묻습니다. 학생이 다음 과제를 제안하는 과정이 있는지 확인하면 단순 제출용 기록과 학습 조정 도구를 구분할 수 있습니다.'),
 ('오답 자료는 수정과 재풀이 연결하기','틀린 문제를 모으는 것만으로 활용이 끝나지 않습니다. 오류의 단계와 수정 이유, 혼자 다시 한 결과를 볼 수 있는지 살펴보세요. 답을 옮겨 쓰는 양보다 다음에 어떤 조건을 먼저 확인할지 정할 수 있는 기록인지 확인합니다.'),
 ('백지노트와 마인드맵은 설명에 활용하기','와와 공식 코칭 안내에는 학습 관리 도구가 소개되어 있습니다. 백지노트는 기억나는 설명을 적고 실제 자료와 비교하는 방식으로, 마인드맵은 개념 관계를 정리하는 방식으로 살펴볼 수 있습니다. 실제 과목별 적용과 확인 방법은 희망 지점에서 질문하세요.'),
 ('AI 결과는 수업과의 연결을 확인하기','점수나 추천 문제를 보는 것과 필요한 지도에 연결하는 일은 다릅니다. 어떤 결과를 선생님이 확인하고 학교 진도와 어떻게 조정하는지 물어보세요. 프로그램의 도입 여부와 대상 학년, 별도 비용은 지점별로 확인해야 하며 모든 지점에 동일하게 제공된다고 가정하지 않습니다.'),
 ('최신이라는 표현보다 실제 자료 보기','도구 이름이 새롭다는 이유만으로 효과를 예측하지 않습니다. 학생 개인 정보를 가린 예시 자료와 활용 순서를 확인하세요. 학생이 이해한 정도와 생활 부담을 보며 필요한 도구를 고르는 것이 비교의 기준입니다.')],
 ('도구별로 물어볼 질문',['질문: 학생의 시도와 막힌 단계는 어떻게 듣나요?','플래너: 미완료 과제는 어떻게 조정하나요?','오답·노트: 독립 재확인은 언제 하나요?','AI: 분석 결과를 누가 수업에 연결하나요?']),
 [('도구가 많을수록 좋은 프로그램인가요?','도구의 개수보다 학생에게 필요한 과제와 연결되는지 확인하세요. 기록 부담이 큰 경우 실제 활용할 항목을 줄일 수 있습니다.'),('공식 안내에 있는 도구를 모든 지점에서 쓰나요?','공식 방향과 개별 운영은 구분해야 합니다. 학년·과목별 적용 여부와 실제 확인 방식을 해당 지점에서 물어보세요.')],['wawa'])

add(29,'중간고사오류분석','중간고사 결과가 아쉬울 때, 오류를 분류하고 다음 계획 세우기',
 '중간고사 시험지의 오류를 개념·읽기·적용·시간으로 나누고, 대표 과제와 다음 시험 준비에 반영할 항목을 정리합니다.',0,'중고','',
 '기대한 결과가 나오지 않았다면 점수에 대한 평가와 다음 공부를 구분해 보세요. 이번 글은 시험지와 풀이 자료를 바탕으로 어떤 오류를 수정할지 정하는 방법입니다. 시험 후 의욕 회복은 별도 글에서 이어서 볼 수 있습니다.',[
 ('시험지와 평가 안내를 함께 준비하기','기억만으로 무엇을 틀렸는지 판단하지 말고 반환된 시험지와 학교 안내를 확인합니다. 문항이나 채점에 궁금한 점이 있다면 담당 선생님에게 확인하세요. 공개되지 않은 자료나 친구의 추측을 바탕으로 점수를 단정하지 않습니다.'),
 ('오류를 네 가지 출발점으로 나누기','개념이나 용어를 몰랐는지, 문제 요구와 조건을 놓쳤는지, 알고도 적용·계산에서 막혔는지, 시간 때문에 끝내지 못했는지 표시합니다. 한 문제에 여러 이유가 있을 수 있습니다. 이 분류는 진단명이 아니라 다음 과제를 고르기 위한 기록입니다.'),
 ('각 유형의 대표 문제 선택하기','모든 오답을 한 번에 다시 쓰기보다 반복된 오류에서 대표 문제를 고릅니다. 개념 오류는 관련 예제 설명, 읽기 오류는 조건 표시, 적용 오류는 독립 풀이, 시간 문제는 풀이 순서와 실제 소요 시간을 확인할 과제로 바꿀 수 있습니다.'),
 ('수정한 내용을 혼자 확인하기','해설을 본 풀이를 다시 맞혔다는 사실만으로 해결됐다고 판단하지 않습니다. 자료를 가리고 이유를 설명하거나 조건이 달라진 기본 과제에 적용해 보세요. 도움받은 부분은 따로 표시해 다음 재확인에서 구분합니다.'),
 ('시험 준비 과정과 연결하기','빠뜨린 학교 자료가 있었는지, 시험 전 질문 시간이 없었는지, 재풀이를 미뤘는지 살펴봅니다. 결과에서 확인한 오류를 준비 행동과 연결하면 바꿀 항목이 보입니다. 한 번의 시험으로 실력 전체나 다음 성적을 예측하지 않습니다.'),
 ('다음 계획에서는 한두 가지 바꾸기','모든 공부 방식을 동시에 바꾸면 실행하기 어려울 수 있습니다. 학교 자료 목록 만들기, 질문할 날짜 정하기, 독립 재확인 칸 남기기 중 필요한 행동을 고르세요. 다음 평가에서는 점수 외에 선택한 준비 행동이 실제로 이어졌는지도 확인합니다.')],
 ('오류와 다음 과제의 연결',['개념: 용어와 기본 예제 설명하기','읽기: 요구 사항과 조건을 자기 말로 쓰기','적용: 받은 힌트를 가리고 독립 재풀이','시간: 막힌 문항과 소요 시간 기록해 순서 조정']),
 [('점수가 낮으면 문제집을 더 풀어야 하나요?','오류의 종류와 학교 자료를 먼저 확인하세요. 개념 설명이나 조건 읽기가 필요한 경우 문제 수를 늘리기 전에 해당 단계를 보완합니다.'),('이번 시험이 다음 성적을 결정하나요?','한 번의 결과만으로 다음 성적을 예측할 수 없습니다. 실제 오류와 준비 과정을 자료로 보고 다음에 바꿀 행동을 정해 보세요.')])

add(30,'새학기학부모준비','새학기 학부모 준비, 기초·생활·도움 요청 함께 점검하기',
 '새학기 전 학생의 기초 과제와 생활 일정, 학교 준비와 도움 요청 방법을 살피고 부모·학생의 역할을 정리합니다.',5,'초중고','',
 '새학기를 준비하면서 교재와 시간표부터 늘리기 전에 지난 학기의 어려움과 지금 생활을 함께 보세요. 부모가 할 준비와 학생이 맡을 행동을 구분하면 필요한 지원을 상담에서 더 구체적으로 확인할 수 있습니다.',[
 ('지난 학기 자료에서 질문 하나 찾기','성적표만 보지 말고 학생이 어려웠던 문제와 과제를 함께 봅니다. 낯선 용어, 혼자 시작하지 못한 풀이, 제출이 늦어진 이유를 구분하세요. 기초 전체가 부족하다고 평가하기보다 다음 수업과 연결될 구체적인 질문을 고릅니다.'),
 ('학기 중 가능한 생활 시간 확인하기','등교 준비, 통학, 식사와 수면, 쉬는 시간을 먼저 배치합니다. 방학 때 가능한 과제량이 학기 중에도 같지는 않을 수 있습니다. 시간표를 고를 때 이동과 귀가 후 과제까지 포함해 학생의 하루 안에 들어가는지 살펴보세요.'),
 ('학교가 안내한 준비 항목 확인하기','교과서와 준비물, 행사와 과제의 일정은 해당 학교 안내를 확인합니다. 다른 학교나 이전 학년의 경험을 현재 사실처럼 적용하지 않습니다. 아직 안내되지 않은 항목은 준비를 과하게 늘리지 말고 확인할 시점을 적어 둡니다.'),
 ('공부가 막혔을 때의 도움 경로 정하기','학생이 질문을 누구에게 어떻게 할 수 있는지 미리 논의합니다. 문제 번호와 시도한 풀이를 남겨 선생님에게 보여 주는 방법부터 시작할 수 있습니다. 학교 생활이나 정서의 어려움은 학습 질문과 구분해서 보호자·학교 상담 담당자에게 알릴 수 있도록 안내하세요.'),
 ('부모의 점검과 학생 역할 나누기','부모는 공식 일정과 비용·통학 조건 확인을, 학생은 자료 준비와 첫 과제 선택을 맡을 수 있습니다. 기록을 볼 시간과 공유 항목을 합의하세요. 학년이 올라갔다는 이유로 모든 계획을 혼자 맡기기보다 가능한 역할을 하나씩 늘립니다.'),
 ('학원 상담에는 실제 자료 가져가기','학교·학년·희망 과목과 최근 어려웠던 과제를 준비합니다. 개설 학년과 질문·복습 방식, 시간·교육비 자료를 함께 확인하세요. 상담 후에는 등록 여부만 결정하기보다 학생에게 어떤 도움을 제공할지와 생활에서 조정할 점을 다시 정리합니다.')],
 ('새학기 전에 함께 확인할 목록',['지난 학기에서 남은 기초 질문 한 가지','학교 준비와 제출 일정의 실제 안내','수면·통학·식사·과제의 생활 시간','부모·학생 역할과 도움 요청 방법']),
 [('새 교재를 미리 많이 사야 하나요?','학교 안내와 현재 필요한 학습 영역을 먼저 확인하세요. 기존 자료로 보완할 부분과 새 교재가 필요한 목적을 나눈 뒤 선택합니다.'),('부모가 계획을 전부 세워줘야 하나요?','일정 확인을 도울 수 있지만 학생이 맡을 준비·선택·기록 역할도 정해 보세요. 실제 가능한 범위와 도움 수준에 맞춰 조정합니다.')])

